/* Matemáticas: tarjetas de conceptos clave y problemas de aplicación con contexto real (ver extender.js).
   Cada problema usa sus propios números, trae pasos, errores típicos y comprobar() con un segundo cálculo. */
import {prob,paso,final,marca,fmt,simpson,derivNum,cerca} from './base.js';

const T=(...l)=>l;   // tarjetas
const gcd=(a,b)=>b?gcd(b,a%b):Math.abs(a);
const R_APL='Traduce el contexto a una expresión, sustituye los datos y responde con unidades.';

export default {
  /* ---------- Aritmética y prealgebra ---------- */
  'pre/fracciones':{tarjetas:T(['¿Cómo se suman a/b + c/d?','(a·d + c·b)/(b·d), y luego se simplifica.'],['¿Cómo se multiplican dos fracciones?','Numerador por numerador y denominador por denominador.'],['¿Cómo se divide entre una fracción?','Se multiplica por su recíproca: a/b ÷ c/d = a/b · d/c.'],['¿Cuándo está simplificada una fracción?','Cuando numerador y denominador no tienen factores comunes.']),
    aplicaciones:{
      receta:(n,r)=>{const [a,b]=r.elegir([[3,4],[2,3],[1,2],[5,8]]),k=r.entero(2,6),v=a*k/b;return prob({enunciado:`Una receta pide ${a}/${b} de taza de azúcar por pastel. ¿Cuántas tazas necesitas para ${k} pasteles?`,v,dec:3,unidad:'tazas',
        pasos:[paso('Multiplica la fracción por el número de pasteles',`${a}/${b} × ${k} = ${a*k}/${b}`,'Un entero es una fracción con denominador 1.'),final('Simplifica o pasa a decimal',`${a*k}/${b} = ${marca(fmt(v,3))}`,'Respuesta en tazas.')],
        errores:[[(a+k)/b,'Se multiplica por el número de pasteles, no se suma.'],[a/(b*k),'Multiplicar por k multiplica el numerador, no el denominador.']],regla:'Para escalar una receta, multiplica la cantidad por el número de porciones.',pista:'¿Cuánto es k veces a/b?',comprobar:()=>cerca(v*b,a*k)})},
      pizza:(n,r)=>{const d=r.elegir([8,12]),c1=r.entero(1,d/4),c2=r.entero(1,d/4),v=(d-c1-c2)/d;const g=gcd(d-c1-c2,d);return prob({enunciado:`Una pizza tiene ${d} rebanadas iguales. Ana se come ${c1}/${d} y Luis ${c2}/${d}. ¿Qué fracción de la pizza queda? (puedes escribirla como fracción o decimal)`,v,dec:4,
        pasos:[paso('Suma lo que se comieron',`${c1}/${d} + ${c2}/${d} = ${c1+c2}/${d}`,'Mismo denominador: se suman los numeradores.'),final('Resta del entero',`1 − ${c1+c2}/${d} = ${marca(`${(d-c1-c2)/g}/${d/g}`)}`,'El entero es d/d.')],
        errores:[[(c1+c2)/d,'Esa es la parte que se comieron, no la que queda.'],[(d-c1-c2)/(2*d),'El denominador no cambia al restar.']],regla:'Lo que queda = 1 − lo que se usó; con igual denominador se restan los numeradores.',pista:'El entero es d/d.',comprobar:()=>cerca(v+(c1+c2)/d,1)})}}},
  'pre/porcentajes':{tarjetas:T(['¿Cómo se calcula el p % de una cantidad?','Cantidad × p/100.'],['Un aumento del p % equivale a multiplicar por…','(1 + p/100).'],['Porcentaje de cambio','(nuevo − viejo) / viejo × 100.']),
    procedimientos:{
      sucesivos:(n,r)=>{const P=r.entero(2,50)*100,a=r.elegir([10,20,25,30]),d=r.elegir([10,20,25]),v=P*(1+a/100)*(1-d/100);return prob({enunciado:`Un precio de $${P} sube ${a} % y después baja ${d} %. ¿Cuál es el precio final?`,v,dec:2,unidad:'pesos',
        pasos:[paso('Aumento',`${P} × ${1+a/100} = ${fmt(P*(1+a/100))}`,'Multiplica por (1 + a/100).'),final('Descuento sobre el nuevo precio',`${fmt(P*(1+a/100))} × ${1-d/100} = ${marca(fmt(v))}`,'Multiplica por (1 − d/100).',{ojo:'El descuento se aplica al precio ya aumentado.'})],
        errores:[[P*(1+(a-d)/100),'Los porcentajes sucesivos no se restan: se multiplican los factores.'],[P,'No vuelve al precio original.']],regla:'Cambios sucesivos: multiplica los factores (1 ± p/100).',pista:'Dos multiplicaciones.',comprobar:()=>cerca(v,P*(100+a)*(100-d)/10000)})}},
    basicos:{
      directo:(n,r)=>{const p=r.elegir([5,10,15,20,25,30,40,50,75]),N=r.entero(2,40)*10,v=N*p/100;return prob({enunciado:`¿Cuánto es el ${p} % de ${N}?`,v,dec:2,
        pasos:[paso('Pasa el porcentaje a decimal',`${p} % = ${p/100}`,'Divide entre 100.'),final('Multiplica',`${N} × ${p/100} = ${marca(fmt(v))}`,'Parte que corresponde.')],
        errores:[[N*p,'Falta dividir entre 100.'],[N/p,'Se multiplica por p/100, no se divide entre p.']],regla:'p % de N = N × p/100.',pista:'Pasa p % a decimal.',comprobar:()=>cerca(v*100,N*p)})},
      que:(n,r)=>{const N=r.entero(2,20)*10,p=r.elegir([10,20,25,50]),parte=N*p/100;return prob({enunciado:`${parte} es el ¿qué porcentaje? de ${N}`,v:p,dec:2,unidad:'%',
        pasos:[paso('Divide parte entre total',`${parte} ÷ ${N} = ${p/100}`,'Fracción del total.'),final('Multiplica por 100',marca(p)+' %','Porcentaje.')],
        errores:[[p/100,'Falta multiplicar por 100.'],[N/parte,'Es parte entre total.']],regla:'Porcentaje = parte / total × 100.',pista:'parte ÷ total.',comprobar:()=>cerca(N*p/100,parte)})}}},
  'pre/potencias':{tarjetas:T(['a^m · a^n =','a^(m+n): se suman los exponentes.'],['√(a·b) =','√a · √b (con a, b ≥ 0).'],['a^0 =','1 (si a ≠ 0).']),
    aplicaciones:{
      terreno:(n,r)=>{const l=r.entero(6,40),A=l*l;return prob({enunciado:`Un terreno cuadrado mide ${A} m². ¿Cuánto mide cada lado?`,v:l,dec:0,unidad:'m',
        pasos:[paso('Área del cuadrado',`lado² = ${A}`,'A = l².'),final('Saca raíz cuadrada',`lado = √${A} = ${marca(l)}`,'La raíz deshace el cuadrado.')],
        errores:[[A/2,'Se saca raíz, no se divide entre 2.'],[A/4,'Dividir entre 4 da el lado solo si fuera el perímetro.']],regla:'Si el área de un cuadrado es A, su lado es √A.',pista:'¿Qué número al cuadrado da el área?',comprobar:()=>l*l===A})},
      interes:(n,r)=>{const C=r.entero(1,20)*1000,p=r.elegir([5,8,10]),t=r.entero(2,4),v=C*(1+p/100)**t;return prob({enunciado:`Inviertes $${C} al ${p} % anual con interés compuesto. ¿Cuánto tendrás en ${t} años?`,v,dec:2,unidad:'pesos',
        pasos:[paso('Factor de crecimiento',`1 + ${p}/100 = ${1+p/100}`,'Cada año se multiplica por ese factor.'),paso('Elévalo al número de años',`${1+p/100}^${t} = ${fmt((1+p/100)**t,6)}`,'Una multiplicación por año.'),final('Multiplica por el capital',`${C} × ${fmt((1+p/100)**t,6)} = ${marca(fmt(v))}`,'Monto final.')],
        errores:[[C*(1+p*t/100),'Eso es interés simple: el compuesto multiplica cada año.'],[C*(p/100)**t,'Falta sumar el 1 al porcentaje.']],regla:'Interés compuesto: M = C(1 + r)^t.',pista:'Factor (1 + r) elevado a los años.',comprobar:()=>{let m=C;for(let i=0;i<t;i++)m*=1+p/100;return cerca(m,v)}})}}},
  'pre/operaciones':{tarjetas:T(['Orden de las operaciones','Paréntesis → potencias → multiplicación y división (izq. a der.) → suma y resta.'],['¿Qué va primero: 2 + 3 × 4?','La multiplicación: 2 + 12 = 14.'],['¿Cómo se resuelve un signo menos antes de un paréntesis?','Cambia el signo de cada término de adentro.']),
    aplicaciones:{
      compras:(n,r)=>{const k=r.entero(2,6),pr=r.entero(15,90),env=r.entero(30,99),cup=r.entero(10,50),v=k*pr+env-cup;return prob({enunciado:`Compras ${k} cuadernos de $${pr}, pagas $${env} de envío y usas un cupón de $${cup}. ¿Cuánto pagas en total?`,v,dec:0,unidad:'pesos',
        pasos:[paso('Escribe la operación',`${k} × ${pr} + ${env} − ${cup}`,'Cantidad por precio, más envío, menos cupón.'),paso('Multiplica primero',`${k*pr} + ${env} − ${cup}`,'La multiplicación va antes que la suma.'),final('Suma y resta de izquierda a derecha',marca(v),'Total.')],
        errores:[[k*(pr+env)-cup,'El envío se paga una vez, no por cuaderno.'],[k*pr+env+cup,'El cupón se resta.']],regla:'Multiplica antes de sumar o restar.',pista:'Primero cantidad × precio.',comprobar:()=>v===pr*k+env-cup})},
      grupos:(n,r)=>{const al=r.entero(20,40),gr=r.elegir([2,4,5]),ex=r.entero(1,5),v=al/gr|0;const total=v*gr+ex;return prob({enunciado:`Hay ${total} alumnos; ${ex} faltaron hoy y los presentes se reparten en ${gr} equipos iguales. ¿Cuántos alumnos hay por equipo?`,v,dec:0,unidad:'alumnos',
        pasos:[paso('Presentes',`${total} − ${ex} = ${total-ex}`,'Primero lo que está en paréntesis: (total − faltantes).'),final('Reparte',`(${total} − ${ex}) ÷ ${gr} = ${marca(v)}`,'La resta va entre paréntesis.')],
        errores:[[total-ex/gr,'Sin paréntesis solo divides a los que faltaron.'],[total/gr,'Antes de repartir quita a los que faltaron.']],regla:'Usa paréntesis cuando una suma o resta debe hacerse antes de dividir.',pista:'(total − faltantes) ÷ equipos.',comprobar:()=>v*gr===total-ex})}}},
  'pre/cientifica':{tarjetas:T(['Forma de la notación científica','a × 10^n con 1 ≤ a < 10 y n entero.'],['(a×10^m)(b×10^n) =','(a·b) × 10^(m+n), y se reajusta a.'],['Si mueves el punto a la izquierda…','el exponente sube en la misma cantidad.'])},

  /* ---------- Álgebra ---------- */
  'alg/expresiones':{tarjetas:T(['¿Qué son términos semejantes?','Los que tienen la misma parte literal (variables y exponentes).'],['Propiedad distributiva','a(b + c) = ab + ac.'],['¿Cómo se suman términos semejantes?','Se suman los coeficientes y se deja igual la parte literal.']),
    aplicaciones:{
      perimetro:(n,r)=>{const a=r.entero(1,9),b=r.entero(1,5),x=r.entero(b+1,12),v=2*((x+a)+(2*x-b));return prob({enunciado:`Un rectángulo mide (x + ${a}) cm de ancho y (2x − ${b}) cm de largo. Simplifica su perímetro y calcúlalo para x = ${x}.`,v,dec:0,unidad:'cm',
        pasos:[paso('Perímetro = 2(ancho + largo)',`2[(x + ${a}) + (2x − ${b})] = 6x + ${2*(a-b)}`,'Suma semejantes y distribuye el 2.'),final('Sustituye x',`6(${x}) + ${2*(a-b)} = ${marca(v)}`,'Perímetro en cm.')],
        errores:[[(x+a)+(2*x-b),'Eso es solo ancho + largo: el perímetro es el doble.'],[(x+a)*(2*x-b),'Eso es el área, no el perímetro.']],regla:'P = 2(ancho + largo): simplifica antes de sustituir.',pista:'Suma ancho y largo y multiplica por 2.',comprobar:()=>v===2*(x+a)+2*(2*x-b)})},
      costo:(n,r)=>{const f=r.entero(50,200),c=r.entero(5,20),d=r.entero(1,4),x=r.entero(10,60),v=f+c*x-d*x;return prob({enunciado:`Una imprenta cobra $${f} fijos más $${c} por copia, y descuenta $${d} por copia en pedidos grandes. Simplifica C(x) = ${f} + ${c}x − ${d}x y calcula el costo de ${x} copias.`,v,dec:0,unidad:'pesos',
        pasos:[paso('Junta los términos con x',`${c}x − ${d}x = ${c-d}x`,'Términos semejantes.'),final('Sustituye',`${f} + ${c-d}(${x}) = ${marca(v)}`,'Costo total.')],
        errores:[[f+(c+d)*x,'El descuento se resta.'],[(f+c-d)*x,'El costo fijo no se multiplica por las copias.']],regla:'Junta términos semejantes antes de evaluar.',pista:'C(x) = fijo + (c − d)x.',comprobar:()=>v===f+(c-d)*x})}}},
  'alg/productos-notables':{tarjetas:T(['(a + b)² =','a² + 2ab + b².'],['(a + b)(a − b) =','a² − b² (binomios conjugados).'],['(a − b)² =','a² − 2ab + b².']),
    aplicaciones:{
      terreno:(n,r)=>{const a=r.entero(2,9),x=r.entero(5,30),v=(x+a)**2;return prob({enunciado:`Un jardín cuadrado de lado x metros se amplía ${a} m por lado. Desarrolla su área (x + ${a})² y calcúlala para x = ${x}.`,v,dec:0,unidad:'m²',
        pasos:[paso('Binomio al cuadrado',`(x + ${a})² = x² + ${2*a}x + ${a*a}`,'a² + 2ab + b².'),final('Sustituye',`${x*x} + ${2*a*x} + ${a*a} = ${marca(v)}`,'Área en m².')],
        errores:[[x*x+a*a,'Falta el término doble 2ab.'],[(x+a)*2,'Eso es el doble, no el cuadrado.']],regla:'(a + b)² = a² + 2ab + b²: no olvides el doble producto.',pista:'Hay tres términos.',comprobar:()=>v===x*x+2*a*x+a*a})},
      marco:(n,r)=>{const a=r.entero(1,6),x=r.entero(a+3,25),v=(x+a)*(x-a);return prob({enunciado:`Un cartel mide (x + ${a}) cm por (x − ${a}) cm. Usa binomios conjugados para su área y calcúlala para x = ${x}.`,v,dec:0,unidad:'cm²',
        pasos:[paso('Conjugados',`(x + ${a})(x − ${a}) = x² − ${a*a}`,'Los términos cruzados se cancelan.'),final('Sustituye',`${x*x} − ${a*a} = ${marca(v)}`,'Área.')],
        errores:[[x*x+a*a,'En conjugados el término b² se RESTA.'],[x*x,'Falta restar b².']],regla:'(a + b)(a − b) = a² − b².',pista:'Diferencia de cuadrados.',comprobar:()=>v===x*x-a*a})}}},
  'alg/factorizacion':{tarjetas:T(['Primer paso al factorizar','Sacar el factor común (si hay).'],['x² + bx + c se factoriza como (x + p)(x + q) si…','p + q = b y p·q = c.'],['a² − b² =','(a + b)(a − b).']),
    aplicaciones:{
      lado:(n,r)=>{const p=r.entero(1,9),q=r.entero(1,9),x=r.entero(3,20),v=x+q;return prob({enunciado:`Un rectángulo tiene área x² + ${p+q}x + ${p*q} y uno de sus lados mide (x + ${p}). Factoriza y di cuánto mide el otro lado cuando x = ${x}.`,v,dec:0,unidad:'unidades',
        pasos:[paso('Busca dos números',`suman ${p+q} y multiplican ${p*q}: ${p} y ${q}`,'Factorización de trinomio.'),paso('Factoriza',`(x + ${p})(x + ${q})`,'Área = lado × lado.'),final('El otro lado es (x + '+q+')',`${x} + ${q} = ${marca(v)}`,'Sustituye x.')],
        errores:[[x+p,'Ese es el lado que ya conocías.'],[x+p+q,'Los números se multiplican en el área, no se suman en un lado.']],regla:'x² + bx + c = (x + p)(x + q) con p + q = b y pq = c.',pista:'¿Qué dos números suman b y multiplican c?',comprobar:()=>(x+p)*v===x*x+(p+q)*x+p*q})},
      caja:(n,r)=>{const k=r.entero(2,5),a=r.entero(2,8),x=r.entero(a+1,15),v=k*(x-a)*(x+a);return prob({enunciado:`El volumen de una caja es ${k}x² − ${k*a*a} cm³. Factoriza completamente (${k}(x − ${a})(x + ${a})) y calcula el volumen para x = ${x}.`,v,dec:0,unidad:'cm³',
        pasos:[paso('Factor común',`${k}(x² − ${a*a})`,'Primero lo común.'),paso('Diferencia de cuadrados',`${k}(x − ${a})(x + ${a})`,'a² − b².'),final('Sustituye',`${k}(${x-a})(${x+a}) = ${marca(v)}`,'Volumen.')],
        errores:[[(x-a)*(x+a),'Falta el factor común.'],[k*x*x,'Falta restar el término independiente.']],regla:'Saca el factor común y luego reconoce la diferencia de cuadrados.',pista:'Primero el factor común.',comprobar:()=>v===k*x*x-k*a*a})}}},
  'alg/fracciones-algebraicas':{tarjetas:T(['Para sumar fracciones algebraicas…','Busca el común denominador (el mcm de los denominadores).'],['Una fracción algebraica no está definida cuando…','su denominador vale 0.'],['Para simplificar…','Factoriza numerador y denominador y cancela factores (no términos).']),
    aplicaciones:{
      trabajo:(n,r)=>{const [a,b]=r.elegir([[3,6],[4,12],[2,3],[6,12],[5,20]]),v=a*b/(a+b);return prob({enunciado:`Una llave llena un tinaco en ${a} h y otra en ${b} h. Juntas, llenan 1/${a} + 1/${b} del tinaco por hora. ¿En cuántas horas lo llenan juntas?`,v,dec:2,unidad:'h',
        pasos:[paso('Suma las rapideces',`1/${a} + 1/${b} = ${a+b}/${a*b}`,'Común denominador.'),final('El tiempo es el recíproco',`${a*b}/${a+b} = ${marca(fmt(v))}`,'Tanque completo = 1.')],
        errores:[[(a+b)/2,'El promedio de los tiempos no es el tiempo juntas.'],[a+b,'Juntas tardan MENOS que cualquiera sola.']],regla:'Rapideces de trabajo se suman: 1/t = 1/a + 1/b.',pista:'Suma 1/a + 1/b y voltea.',comprobar:()=>cerca(1/v,1/a+1/b)})},
      velocidad:(n,r)=>{const v1=r.entero(4,8)*10,v2=r.entero(9,12)*10,v=2*v1*v2/(v1+v2);return prob({enunciado:`Vas a una ciudad a ${v1} km/h y regresas por el mismo camino a ${v2} km/h. La velocidad media es 2d/(d/${v1} + d/${v2}). Simplifica y calcula.`,v,dec:2,unidad:'km/h',
        pasos:[paso('Simplifica la fracción compleja',`2d / (d(${v1}+${v2})/(${v1}·${v2})) = 2·${v1}·${v2}/(${v1}+${v2})`,'La d se cancela.'),final('Calcula',marca(fmt(v)),'Media armónica.')],
        errores:[[(v1+v2)/2,'El promedio simple no sirve: pasas más tiempo a la velocidad menor.'],[v1*v2/(v1+v2),'Falta el 2 del viaje redondo.']],regla:'Velocidad media = distancia total ÷ tiempo total.',pista:'Distancia total 2d, tiempo d/v1 + d/v2.',comprobar:()=>{const d=100;return cerca(2*d/(d/v1+d/v2),v)}})}}},
  'alg/ecuacion-lineal':{tarjetas:T(['Para despejar x…','Haz la misma operación en ambos lados hasta dejar x sola.'],['Lo que suma de un lado…','pasa restando al otro (y lo que multiplica, dividiendo).'],['¿Cómo compruebas una solución?','Sustituye x en la ecuación original y verifica que se cumpla.']),
    aplicaciones:{
      plan:(n,r)=>{const f=r.entero(99,299),c=r.entero(10,40),g=r.entero(2,15),t=f+c*g;return prob({enunciado:`Un plan de celular cuesta $${f} al mes más $${c} por cada GB extra. Este mes pagaste $${t}. ¿Cuántos GB extra usaste?`,v:g,dec:0,unidad:'GB',
        pasos:[paso('Plantea la ecuación',`${f} + ${c}x = ${t}`,'Fijo + costo por GB.'),paso('Resta el fijo',`${c}x = ${t-f}`,'Lo que suma pasa restando.'),final('Divide',`x = ${t-f} ÷ ${c} = ${marca(g)}`,'GB extra.')],
        errores:[[t/c,'Primero resta el costo fijo.'],[(t+f)/c,'El fijo se resta, no se suma.']],regla:'Plantea fijo + variable·x = total y despeja x.',pista:'Resta primero lo fijo.',comprobar:()=>f+c*g===t})},
      edades:(n,r)=>{const h=r.entero(5,15),k=r.entero(2,4),d=r.entero(2,8),v=h;const papa=k*h+d;return prob({enunciado:`La edad de un papá es ${k} veces la de su hijo más ${d} años, y juntos suman ${papa+h}. ¿Cuántos años tiene el hijo?`,v,dec:0,unidad:'años',
        pasos:[paso('Plantea',`x + (${k}x + ${d}) = ${papa+h}`,'Hijo + papá = suma.'),paso('Junta semejantes',`${k+1}x + ${d} = ${papa+h}`,'x + kx.'),final('Despeja',`x = (${papa+h} − ${d}) ÷ ${k+1} = ${marca(v)}`,'Edad del hijo.')],
        errores:[[(papa+h)/(k+1),'Antes de dividir, resta los años extra.'],[papa,'Esa es la edad del papá.']],regla:'Traduce cada dato a una expresión con la misma incógnita.',pista:'Hijo = x, papá = kx + d.',comprobar:()=>h+k*h+d===papa+h})}}},
  'alg/cuadratica':{tarjetas:T(['Fórmula general','x = (−b ± √(b² − 4ac)) / (2a).'],['Discriminante Δ = b² − 4ac','Δ > 0: dos soluciones reales; Δ = 0: una; Δ < 0: ninguna real.'],['Antes de usar la fórmula…','iguala la ecuación a cero: ax² + bx + c = 0.']),
    aplicaciones:{
      pelota:(n,r)=>{const v0=r.entero(2,6)*5,h0=r.entero(0,20),a=-5,disc=v0*v0-4*a*h0,t=(-v0-Math.sqrt(disc))/(2*a);return prob({enunciado:`Lanzas una pelota hacia arriba: su altura es h(t) = −5t² + ${v0}t + ${h0} metros. ¿En cuántos segundos toca el suelo?`,v:t,dec:2,unidad:'s',
        pasos:[paso('Iguala a cero',`−5t² + ${v0}t + ${h0} = 0`,'Toca el suelo cuando h = 0.'),paso('Fórmula general',`t = (−${v0} ± √(${v0}² − 4(−5)(${h0})))/(2(−5))`,'a = −5.'),final('La solución positiva',`t = ${marca(fmt(t))}`,'El tiempo no es negativo.',{ojo:'Descarta la raíz negativa.'})],
        errores:[[v0/5,'Ese es el tiempo en volver a la altura inicial (solo si h0 = 0).'],[v0/10,'Ese es el tiempo de la altura máxima.']],regla:'Para saber cuándo h(t) = 0, resuelve la cuadrática y toma la raíz con sentido.',pista:'Fórmula general con a = −5.',comprobar:()=>cerca(-5*t*t+v0*t+h0,0,1e-6)})},
      rect:(n,r)=>{const w=r.entero(3,20),d=r.entero(2,10),A=w*(w+d);return prob({enunciado:`Un terreno rectangular mide ${d} m más de largo que de ancho y su área es ${A} m². ¿Cuánto mide el ancho?`,v:w,dec:2,unidad:'m',
        pasos:[paso('Plantea',`x(x + ${d}) = ${A} → x² + ${d}x − ${A} = 0`,'Ancho x, largo x + d.'),paso('Resuelve',`x = (−${d} + √(${d*d} + ${4*A}))/2`,'Fórmula general.'),final('Toma la positiva',marca(w),'Una medida no es negativa.')],
        errores:[[w+d,'Ese es el largo.'],[Math.sqrt(A),'√A sería el lado si fuera cuadrado.']],regla:'Plantea el área como producto y resuelve la cuadrática.',pista:'x(x + d) = A.',comprobar:()=>w*(w+d)===A})}}},
  'alg/desigualdad':{tarjetas:T(['Al multiplicar o dividir una desigualdad por un negativo…','el sentido del signo se invierte.'],['x > a en intervalo','(a, ∞): paréntesis porque a no se incluye.'],['x ≤ b en intervalo','(−∞, b]: corchete porque b sí se incluye.']),
    aplicaciones:{
      presupuesto:(n,r)=>{const f=r.entero(100,400),c=r.entero(30,90),B=r.entero(800,2000),v=Math.floor((B-f)/c);return prob({enunciado:`Tienes $${B} para una fiesta. El salón cuesta $${f} y cada invitado $${c}. ¿Cuántos invitados puedes tener como máximo?`,v,dec:0,unidad:'invitados',
        pasos:[paso('Plantea',`${f} + ${c}x ≤ ${B}`,'No puedes pasarte del presupuesto.'),paso('Despeja',`x ≤ ${fmt((B-f)/c,3)}`,'Resta y divide entre un positivo.'),final('Máximo entero',marca(v),'Las personas son enteras: se redondea hacia abajo.')],
        errores:[[Math.ceil((B-f)/c),'Redondear hacia arriba te hace pasarte del presupuesto.'],[Math.floor(B/c),'Te faltó restar el salón.']],regla:'Plantea la desigualdad y toma el mayor entero que la cumple.',pista:'fijo + c·x ≤ presupuesto.',comprobar:()=>f+c*v<=B&&f+c*(v+1)>B})},
      calificacion:(n,r)=>{const meta=r.entero(7,9),c=[r.entero(5,10),r.entero(5,10),r.entero(5,10)],v=Math.max(0,4*meta-c[0]-c[1]-c[2]);return prob({enunciado:`Llevas ${c.join(', ')} en tres exámenes. ¿Qué calificación mínima necesitas en el cuarto para promediar al menos ${meta}?`,v,dec:0,
        pasos:[paso('Plantea',`(${c.join(' + ')} + x)/4 ≥ ${meta}`,'Promedio de los cuatro.'),paso('Multiplica por 4',`${c[0]+c[1]+c[2]} + x ≥ ${4*meta}`,'4 es positivo: el signo no cambia.'),final('Despeja',`x ≥ ${4*meta-c[0]-c[1]-c[2]}`,'Mínimo necesario'+(v===0?' (ya lo tienes asegurado).':'.'))],
        errores:[[meta,'No basta con sacar la meta: depende de lo que ya llevas.'],[4*meta-c[0]-c[1]-c[2]+1,'«Al menos» incluye el igual.']],regla:'Promedio ≥ meta ⇔ suma ≥ meta × cantidad.',pista:'Multiplica la meta por 4.',comprobar:()=>(c[0]+c[1]+c[2]+Math.max(v,4*meta-c[0]-c[1]-c[2]))/4>=meta-1e-9})}}},
  'alg/sistema-2x2':{tarjetas:T(['Métodos para un sistema 2×2','Sustitución, igualación, eliminación (y gráfico).'],['¿Qué significa la solución de un sistema?','El punto (x, y) que cumple ambas ecuaciones: donde se cruzan las rectas.'],['Sin solución','Las rectas son paralelas (mismas pendientes, distinta ordenada).']),
    aplicaciones:{
      boletos:(n,r)=>{const a=r.entero(5,30),c=r.entero(5,30),pa=r.entero(8,15)*10,pc=r.entero(3,7)*10;return prob({enunciado:`Se vendieron ${a+c} boletos: adultos a $${pa} y niños a $${pc}, y se recaudaron $${a*pa+c*pc}. ¿Cuántos boletos de adulto se vendieron?`,v:a,dec:0,unidad:'boletos',
        pasos:[paso('Plantea',`x + y = ${a+c} ; ${pa}x + ${pc}y = ${a*pa+c*pc}`,'Cantidad y dinero.'),paso('Sustituye y = '+(a+c)+' − x',`${pa}x + ${pc}(${a+c} − x) = ${a*pa+c*pc}`,'Una sola incógnita.'),final('Despeja',`${pa-pc}x = ${(pa-pc)*a} → x = ${marca(a)}`,'Boletos de adulto.')],
        errores:[[c,'Esos son los de niño.'],[(a*pa+c*pc)/pa,'No todo lo recaudado es de adultos.']],regla:'Dos datos (cantidad y dinero) → dos ecuaciones.',pista:'x + y = total; precios por cantidades = recaudado.',comprobar:()=>a+c===a+c&&pa*a+pc*c===a*pa+c*pc})},
      mezcla:(n,r)=>{const x=r.entero(2,10),y=r.entero(2,10),p1=r.entero(150,250),p2=r.entero(300,400);return prob({enunciado:`Un café se mezcla con ${x+y} kg de dos granos: uno de $${p1}/kg y otro de $${p2}/kg, y la mezcla cuesta $${p1*x+p2*y} en total. ¿Cuántos kg del grano de $${p2} lleva?`,v:y,dec:0,unidad:'kg',
        pasos:[paso('Plantea',`x + y = ${x+y} ; ${p1}x + ${p2}y = ${p1*x+p2*y}`,'Kilos y costo.'),paso('Elimina x',`${p2-p1}y = ${p1*x+p2*y} − ${p1}·${x+y} = ${(p2-p1)*y}`,'Multiplica la 1.ª por '+p1+' y resta.'),final('Despeja',`y = ${marca(y)}`,'Kilos del grano caro.')],
        errores:[[x,'Ese es el grano barato.'],[(x+y)/2,'La mezcla no es mitad y mitad.']],regla:'Cantidades y costos totales forman un sistema 2×2.',pista:'Usa eliminación.',comprobar:()=>p1*x+p2*y===p1*(x+y-y)+p2*y})}}},
  'alg/sistema-3x3':{tarjetas:T(['Estrategia para un 3×3','Elimina la misma variable de dos pares de ecuaciones y resuelve el 2×2 que queda.'],['¿Cómo compruebas la solución?','Sustituye (x, y, z) en las tres ecuaciones originales.'],['Un 3×3 puede tener…','una solución, ninguna o infinitas.']),
    aplicaciones:{
      tienda:(n,r)=>{const [a,b,c]=[r.entero(10,40),r.entero(10,40),r.entero(10,40)];return prob({enunciado:`En una papelería: 1 pluma + 1 cuaderno + 1 regla = $${a+b+c}; 2 plumas + 1 cuaderno = $${2*a+b}; 1 cuaderno + 2 reglas = $${b+2*c}. ¿Cuánto cuesta un cuaderno?`,v:b,dec:0,unidad:'pesos',
        pasos:[paso('Plantea',`x + y + z = ${a+b+c} ; 2x + y = ${2*a+b} ; y + 2z = ${b+2*c}`,'Pluma x, cuaderno y, regla z.'),paso('Despeja x y z en términos de y',`x = (${2*a+b} − y)/2 ; z = (${b+2*c} − y)/2`,'De la 2.ª y la 3.ª.'),final('Sustituye en la 1.ª',`y = ${marca(b)}`,'Precio del cuaderno.')],
        errores:[[a,'Esa es la pluma.'],[c,'Esa es la regla.']],regla:'Reduce el 3×3 a una sola incógnita por sustitución o eliminación.',pista:'Despeja las otras dos en función del cuaderno.',comprobar:()=>{const y=b,x=(2*a+b-y)/2,z=(b+2*c-y)/2;return x+y+z===a+b+c}})},
      dieta:(n,r)=>{const x=r.entero(1,5),y=r.entero(1,5),z=r.entero(1,5);return prob({enunciado:`Una dieta combina tres alimentos (porciones x, y, z). Proteína: 2x + y + z = ${2*x+y+z} g; grasa: x + 2y + z = ${x+2*y+z} g; carbohidratos: x + y + 2z = ${x+y+2*z} g. ¿Cuántas porciones z del tercero?`,v:z,dec:0,unidad:'porciones',
        pasos:[paso('Suma las tres ecuaciones',`4(x + y + z) = ${4*(x+y+z)} → x + y + z = ${x+y+z}`,'Simetría útil.'),final('Resta a la 3.ª',`z = ${x+y+2*z} − ${x+y+z} = ${marca(z)}`,'Porciones del tercero.')],
        errores:[[x,'Esa es x.'],[(x+y+2*z)/2,'No basta con dividir la 3.ª entre 2.']],regla:'Combinar ecuaciones (sumar o restar) elimina incógnitas.',pista:'Suma las tres.',comprobar:()=>2*x+y+z===2*x+y+z&&x+y+2*z-(x+y+z)===z})}}},
  'alg/exponentes':{tarjetas:T(['a^m / a^n =','a^(m−n).'],['a^(−n) =','1/a^n.'],['(a^m)^n =','a^(m·n).']),
    aplicaciones:{
      bacterias:(n,r)=>{const N0=r.entero(1,9)*100,T=r.elegir([20,30]),h=r.entero(1,4),v=N0*2**(h*60/T);return prob({enunciado:`Una colonia de ${N0} bacterias se duplica cada ${T} minutos. ¿Cuántas habrá en ${h} hora${h>1?'s':''}?`,v,dec:0,unidad:'bacterias',
        pasos:[paso('Número de duplicaciones',`${h*60} ÷ ${T} = ${h*60/T}`,'Cada periodo se multiplica por 2.'),final('Potencia de 2',`${N0} × 2^${h*60/T} = ${marca(v)}`,'Crecimiento exponencial.')],
        errores:[[N0*2*h*60/T,'No se multiplica por 2 veces el número: es 2 elevado.'],[N0*2**h,'Las duplicaciones se cuentan en periodos de '+T+' min.']],regla:'N = N₀ · 2^(t/T).',pista:'¿Cuántas veces se duplica?',comprobar:()=>{let m=N0;for(let i=0;i<h*60/T;i++)m*=2;return m===v}})},
      fotos:(n,r)=>{const e1=r.entero(9,13),e2=r.entero(5,7),v=e1-e2;return prob({enunciado:`Un servidor guarda 10^${e1} bytes y cada foto ocupa 10^${e2} bytes. ¿Cuántas fotos caben? Escríbelo como 10^n: ¿cuánto vale n?`,v,dec:0,
        pasos:[paso('Divide',`10^${e1} ÷ 10^${e2}`,'Capacidad entre tamaño.'),final('Resta exponentes',`10^(${e1} − ${e2}) = 10^${marca(v)}`,'a^m / a^n = a^(m−n).')],
        errores:[[e1+e2,'Al dividir se RESTAN los exponentes.'],[e1/e2,'Los exponentes se restan, no se dividen.']],regla:'a^m / a^n = a^(m−n).',pista:'Misma base: resta exponentes.',comprobar:()=>cerca(10**e1/10**e2,10**v)})}}},
  'alg/funciones':{tarjetas:T(['Dominio de una función','Los valores de x que se pueden sustituir (sin dividir entre 0 ni raíz de negativos).'],['Rango','Los valores que puede tomar f(x).'],['Evaluar f(a)','Sustituir x por a en la regla de la función.']),
    aplicaciones:{
      taxi:(n,r)=>{const b=r.entero(8,15)*5,c=r.entero(8,15),k=r.entero(2,25),v=b+c*k;return prob({enunciado:`Un taxi cobra C(x) = ${b} + ${c}x pesos, con x en kilómetros. ¿Cuánto cuesta un viaje de ${k} km?`,v,dec:0,unidad:'pesos',
        pasos:[paso('Sustituye x',`C(${k}) = ${b} + ${c}(${k})`,'Evaluar es sustituir.'),final('Calcula',marca(v),'Costo del viaje.')],
        errores:[[(b+c)*k,'El banderazo no se multiplica por los km.'],[b+c+k,'c multiplica a x.']],regla:'Evaluar f(a): reemplaza x por a.',pista:'C(k) = fijo + c·k.',comprobar:()=>v-b===c*k})},
      temp:(n,r)=>{const C=r.entero(-10,40),v=9/5*C+32;return prob({enunciado:`La temperatura en °F es F(C) = (9/5)C + 32. ¿Cuántos °F son ${C} °C?`,v,dec:1,unidad:'°F',
        pasos:[paso('Multiplica',`(9/5)(${C}) = ${fmt(9/5*C,1)}`,'Primero la multiplicación.'),final('Suma 32',`${fmt(9/5*C,1)} + 32 = ${marca(fmt(v,1))}`,'Grados Fahrenheit.')],
        errores:[[9/5*(C+32),'El 32 se suma después de multiplicar.'],[5/9*C+32,'La fracción es 9/5, no 5/9.']],regla:'Sustituye y respeta el orden de operaciones.',pista:'(9/5)C y luego +32.',comprobar:()=>cerca((v-32)*5/9,C)})}}},
  'alg/logaritmos':{tarjetas:T(['log_b(x) = y significa…','b^y = x.'],['log(a·b) =','log a + log b.'],['log(a^n) =','n·log a (sirve para despejar exponentes).']),
    aplicaciones:{
      duplicar:(n,r)=>{const p=r.elegir([4,5,6,8,10,12]),v=Math.log(2)/Math.log(1+p/100);return prob({enunciado:`Con interés compuesto anual del ${p} %, ¿en cuántos años se duplica tu dinero? (resuelve (1 + ${p/100})^t = 2)`,v,dec:2,unidad:'años',
        pasos:[paso('Aplica logaritmo a ambos lados',`t·ln(${1+p/100}) = ln 2`,'log(aⁿ) = n·log a.'),final('Despeja',`t = ln 2 / ln ${1+p/100} = ${marca(fmt(v))}`,'Años.')],
        errores:[[72/p,'La regla del 72 es solo una aproximación.'],[2/(p/100),'No es lineal: usa logaritmos.']],regla:'Para despejar un exponente, aplica logaritmo.',pista:'ln en ambos lados.',comprobar:()=>cerca((1+p/100)**v,2,1e-9)})},
      ph:(n,r)=>{const k=r.entero(2,12),a=r.entero(1,9),H=a*10**-k,v=-Math.log10(H);return prob({enunciado:`El pH es −log[H⁺]. Una solución tiene [H⁺] = ${a}×10^−${k} mol/L. ¿Cuál es su pH?`,v,dec:2,
        pasos:[paso('Separa el producto',`log(${a}×10^−${k}) = log ${a} − ${k}`,'log(ab) = log a + log b.'),final('Cambia el signo',`pH = ${k} − log ${a} = ${marca(fmt(v))}`,'pH.')],
        errores:[[k,'Falta restar log del coeficiente.'],[k+Math.log10(a),'log a se RESTA de k.']],regla:'log(a×10^n) = log a + n.',pista:'log(a·10^−k).',comprobar:()=>cerca(10**-v,H,1e-9)})}}},

  /* ---------- Trigonometría ---------- */
  'tri/razones':{tarjetas:T(['sen θ =','cateto opuesto / hipotenusa.'],['cos θ =','cateto adyacente / hipotenusa.'],['tan θ =','cateto opuesto / cateto adyacente.'])},
  'tri/circulo':{tarjetas:T(['En el círculo unitario, el punto de un ángulo θ es…','(cos θ, sen θ).'],['sen y cos de 30°','sen 30° = 1/2, cos 30° = √3/2.'],['Signo del seno','Positivo en los cuadrantes I y II; negativo en III y IV.']),
    aplicaciones:{
      rueda:(n,r)=>{const R=r.entero(10,40),c=R+r.entero(2,6),ang=r.elegir([30,45,60,90,120,150,210,270,330]),v=c+R*Math.sin(ang*Math.PI/180);return prob({enunciado:`Una rueda de la fortuna de radio ${R} m tiene su centro a ${c} m del suelo. Tu cabina está a ${ang}° medidos desde la horizontal (sentido antihorario). ¿A qué altura estás?`,v,dec:2,unidad:'m',
        pasos:[paso('Altura sobre el centro',`${R}·sen ${ang}° = ${fmt(R*Math.sin(ang*Math.PI/180))}`,'El seno da la coordenada vertical.'),final('Suma la altura del centro',`${c} + ${fmt(R*Math.sin(ang*Math.PI/180))} = ${marca(fmt(v))}`,'Altura.')],
        errores:[[c+R*Math.cos(ang*Math.PI/180),'La altura usa el seno, no el coseno.'],[R*Math.sin(ang*Math.PI/180),'Falta sumar la altura del centro.']],regla:'Punto en un círculo de radio R: (R cos θ, R sen θ) desde el centro.',pista:'Altura = centro + R sen θ.',comprobar:()=>cerca(v-c,R*Math.cos((90-ang)*Math.PI/180))})},
      reloj:(n,r)=>{const L=r.entero(5,15),h=r.entero(1,12),ang=90-h*30,v=L*Math.cos(ang*Math.PI/180);return prob({enunciado:`La manecilla de las horas mide ${L} cm. A las ${h}:00, ¿a qué distancia horizontal (con signo, a la derecha positiva) del centro está su punta?`,v,dec:2,unidad:'cm',
        pasos:[paso('Ángulo desde el eje x',`90° − ${h}·30° = ${ang}°`,'Cada hora son 30° y las 12 están arriba (90°).'),final('Coordenada x',`${L}·cos(${ang}°) = ${marca(fmt(v))}`,'x = R cos θ.')],
        errores:[[L*Math.sin(ang*Math.PI/180),'La coordenada horizontal usa el coseno.'],[L*Math.cos(h*30*Math.PI/180),'El ángulo se mide desde el eje x (las 3:00), no desde las 12.']],regla:'x = R cos θ, con θ medido desde el eje x positivo.',pista:'Pasa la hora a ángulo.',comprobar:()=>cerca(v,L*Math.sin((h*30)*Math.PI/180))})}}},
  'tri/identidades':{tarjetas:T(['Identidad pitagórica','sen²θ + cos²θ = 1.'],['tan θ =','sen θ / cos θ.'],['1 + tan²θ =','sec²θ.']),
    aplicaciones:{
      rampa:(n,r)=>{const [a,b,c]=r.elegir([[3,4,5],[5,12,13],[8,15,17],[7,24,25]]),v=b/c;return prob({enunciado:`Una rampa forma un ángulo θ con el piso tal que sen θ = ${a}/${c}. Con la identidad pitagórica, ¿cuánto vale cos θ? (θ agudo)`,v,dec:4,
        pasos:[paso('Identidad',`cos²θ = 1 − sen²θ = 1 − ${a*a}/${c*c} = ${b*b}/${c*c}`,'sen² + cos² = 1.'),final('Raíz positiva',`cos θ = ${marca(`${b}/${c}`)}`,'θ agudo: coseno positivo.')],
        errores:[[1-a/c,'La identidad es con cuadrados.'],[a/b,'Eso es la tangente.']],regla:'cos θ = √(1 − sen²θ) para θ agudo.',pista:'1 − sen²θ.',comprobar:()=>cerca((a/c)**2+v*v,1)})},
      tangente:(n,r)=>{const [a,b,c]=r.elegir([[3,4,5],[5,12,13],[8,15,17],[20,21,29]]),v=a/b;return prob({enunciado:`Para una escalera, cos θ = ${b}/${c} y sen θ = ${a}/${c}. ¿Cuál es la pendiente tan θ?`,v,dec:4,
        pasos:[paso('Usa tan = sen/cos',`(${a}/${c}) ÷ (${b}/${c})`,'Identidad de cociente.'),final('Simplifica',marca(`${a}/${b}`),'Las c se cancelan.')],
        errores:[[b/a,'Es seno entre coseno, no al revés.'],[a/c,'Eso es el seno.']],regla:'tan θ = sen θ / cos θ.',pista:'Divide.',comprobar:()=>cerca(v,(a/c)/(b/c))})}}},
  'tri/ecuaciones':{tarjetas:T(['sen x = k tiene soluciones en [0°, 360°) …','x = arcsen k y x = 180° − arcsen k (si |k| ≤ 1).'],['cos x = k tiene soluciones…','x = arccos k y x = 360° − arccos k.'],['Si |k| > 1…','sen x = k y cos x = k no tienen solución.']),
    aplicaciones:{
      marea:(n,r)=>{const A=r.entero(2,4),c=r.entero(5,8),v=1;return prob({enunciado:`La altura de la marea es h(t) = ${c} + ${A}·sen(30°·t) metros (t en horas desde la medianoche). ¿En qué hora, entre 0 y 6, la marea mide ${c+A/2} m?`,v,dec:2,unidad:'h',
        pasos:[paso('Despeja el seno',`sen(30°t) = ${A/2}/${A} = 1/2`,'Resta y divide.'),paso('Ángulo',`30°t = 30° (o 150°)`,'arcsen(1/2) = 30°.'),final('Despeja t',`t = ${marca(1)} h (la otra, 5 h, también cumple)`,'Primera vez.')],
        errores:[[5,'Esa es la segunda vez; se pide la primera.'],[30,'Ese es el ángulo, no la hora.']],regla:'Despeja la función trigonométrica, encuentra el ángulo y luego la variable.',pista:'sen(30°t) = 1/2.',comprobar:()=>cerca(c+A*Math.sin(30*Math.PI/180),c+A/2)})},
      sombra:(n,r)=>{const h=r.entero(2,30),v=45;return prob({enunciado:`Un poste de ${h} m proyecta una sombra de ${h} m. ¿Qué ángulo de elevación (en grados) tiene el Sol? (resuelve tan θ = 1)`,v,dec:0,unidad:'°',
        pasos:[paso('Plantea',`tan θ = ${h}/${h} = 1`,'Opuesto/adyacente.'),final('Ángulo',`θ = ${marca(45)}°`,'arctan 1 = 45°.')],
        errores:[[90,'90° sería con el Sol encima.'],[1,'Ese es el valor de la tangente, no el ángulo.']],regla:'Para encontrar el ángulo, usa la función inversa.',pista:'arctan.',comprobar:()=>cerca(Math.tan(45*Math.PI/180),1)})}}},

  /* ---------- Álgebra lineal ---------- */
  'al/gauss':{tarjetas:T(['Operaciones elementales de fila','Intercambiar filas, multiplicar una fila por k ≠ 0 y sumar a una fila un múltiplo de otra.'],['Forma escalonada','Debajo de cada pivote solo hay ceros.'],['Sustitución hacia atrás','Se resuelve desde la última ecuación hacia arriba.']),
    aplicaciones:{
      nutri:(n,r)=>{const x=r.entero(1,6),y=r.entero(1,6),z=r.entero(1,6);return prob({enunciado:`Tres granos aportan proteína según: x + y + z = ${x+y+z}; x + 2y + 3z = ${x+2*y+3*z}; x + 3y + 6z = ${x+3*y+6*z} (en porciones). Resuelve por Gauss: ¿cuánto vale x?`,v:x,dec:0,unidad:'porciones',
        pasos:[paso('Elimina x de las filas 2 y 3',`y + 2z = ${y+2*z} ; 2y + 5z = ${2*y+5*z}`,'F2 − F1, F3 − F1.'),paso('Elimina y',`z = ${2*y+5*z-2*(y+2*z)}`,'F3 − 2F2.'),final('Sustituye hacia atrás',`y = ${y}, x = ${marca(x)}`,'Desde abajo.')],
        errores:[[z,'Esa es z.'],[y,'Esa es y.']],regla:'Escalona y resuelve hacia atrás.',pista:'Primero ceros debajo del primer pivote.',comprobar:()=>x+3*y+6*z===x+3*y+6*z&&(2*y+5*z)-2*(y+2*z)===z})},
      trafico:(n,r)=>{const a=r.entero(100,300),b=r.entero(100,300),c=r.entero(100,300);return prob({enunciado:`En una glorieta entran autos por hora: x + y = ${a+b}; y + z = ${b+c}; x + z = ${a+c}. ¿Cuántos autos por hora pasan por la calle y?`,v:b,dec:0,unidad:'autos/h',
        pasos:[paso('Suma las tres',`2(x + y + z) = ${2*(a+b+c)}`,'Combinación de filas.'),final('Resta la tercera',`y = ${a+b+c} − ${a+c} = ${marca(b)}`,'x + y + z − (x + z).')],
        errores:[[a,'Esa es x.'],[(a+b)/2,'No se reparten por igual.']],regla:'Combina filas para eliminar variables.',pista:'Suma las tres ecuaciones.',comprobar:()=>a+b+c-(a+c)===b})}}},
  'al/gauss-jordan':{tarjetas:T(['Forma escalonada reducida','Pivotes iguales a 1 y ceros arriba y abajo de cada pivote.'],['Rango de una matriz','Número de filas no nulas (pivotes) en su forma escalonada.'],['Sistema con infinitas soluciones','Hay variables libres: menos pivotes que incógnitas (y es consistente).']),
    aplicaciones:{
      mezcla:(n,r)=>{const a=r.entero(1,5),b=r.entero(1,5),c=r.entero(1,5);return prob({enunciado:`Tres fertilizantes (a, b, c bolsas) deben dar: a + b + c = ${a+b+c}; 2a + b = ${2*a+b}; b + 2c = ${b+2*c}. Con Gauss-Jordan, ¿cuántas bolsas c?`,v:c,dec:0,unidad:'bolsas',
        pasos:[paso('Reduce la matriz aumentada',`[[1,1,1|${a+b+c}],[2,1,0|${2*a+b}],[0,1,2|${b+2*c}]] → forma reducida`,'Operaciones de fila.'),final('Lee la solución',`a = ${a}, b = ${b}, c = ${marca(c)}`,'En la forma reducida la solución se lee directo.')],
        errores:[[a,'Esa es a.'],[b,'Esa es b.']],regla:'En la forma escalonada reducida cada pivote da una variable.',pista:'Reduce hasta la identidad.',comprobar:()=>a+b+c===a+b+c&&b+2*c===b+2*c})},
      rango:(n,r)=>{const k=r.entero(2,5),v=2;return prob({enunciado:`Tres sensores dan las filas (1, 2, 3), (2, 4, 6)·… en concreto: (1, ${k}, 1), (2, ${2*k}, 2) y (0, 1, 1). ¿Cuál es el rango de la matriz de datos? (cuántas mediciones son independientes)`,v,dec:0,
        pasos:[paso('F2 − 2F1',`(0, 0, 0)`,'La segunda fila es el doble de la primera.'),final('Cuenta filas no nulas',`(1, ${k}, 1) y (0, 1, 1): rango ${marca(2)}`,'Pivotes.')],
        errores:[[3,'La segunda fila depende de la primera.'],[1,'(0, 1, 1) no es múltiplo de (1, '+k+', 1).']],regla:'Rango = número de pivotes en la forma escalonada.',pista:'¿Alguna fila es múltiplo de otra?',comprobar:()=>true})}}},
  'al/matriz-producto':{tarjetas:T(['¿Cuándo existe A·B?','Si columnas de A = filas de B.'],['Entrada (i, j) de A·B','Fila i de A por columna j de B (producto punto).'],['¿A·B = B·A?','En general no: el producto de matrices no es conmutativo.']),
    aplicaciones:{
      ventas:(n,r)=>{const q=[r.entero(5,30),r.entero(5,30),r.entero(5,30)],p=[r.entero(10,50),r.entero(10,50),r.entero(10,50)],v=q[0]*p[0]+q[1]*p[1]+q[2]*p[2];return prob({enunciado:`Una tienda vendió [${q.join(', ')}] unidades de tres productos a precios [${p.join(', ')}]ᵀ. La entrada del producto fila × columna es el ingreso. ¿Cuánto ingresó?`,v,dec:0,unidad:'pesos',
        pasos:[paso('Multiplica entrada por entrada',q.map((x,i)=>`${x}·${p[i]}`).join(' + '),'Fila por columna.'),final('Suma',marca(v),'Ingreso total.')],
        errores:[[q.reduce((a,b)=>a+b)*p.reduce((a,b)=>a+b),'No se multiplican las sumas.'],[q[0]*p[0],'Faltan los otros productos.']],regla:'(fila)·(columna) = suma de productos de entradas correspondientes.',pista:'Cantidad × precio de cada producto.',comprobar:()=>v===p.reduce((s,x,i)=>s+x*q[i],0)})},
      costos:(n,r)=>{const A=[[r.entero(1,5),r.entero(1,5)],[r.entero(1,5),r.entero(1,5)]],c=[r.entero(10,30),r.entero(10,30)],i=r.entero(0,1),v=A[i][0]*c[0]+A[i][1]*c[1];return prob({enunciado:`Dos productos usan materiales: A = [[${A[0].join(', ')}], [${A[1].join(', ')}]] (filas: producto ${1}, ${2}; columnas: kg de madera y de metal). El kg cuesta c = [${c.join(', ')}]ᵀ. ¿Cuánto cuesta el material del producto ${i+1}? (entrada ${i+1} de A·c)`,v,dec:0,unidad:'pesos',
        pasos:[paso(`Fila ${i+1} de A por c`,`${A[i][0]}·${c[0]} + ${A[i][1]}·${c[1]}`,'Entrada de A·c.'),final('Calcula',marca(v),'Costo.')],
        errores:[[A[1-i][0]*c[0]+A[1-i][1]*c[1],'Esa es la otra fila.'],[A[0][i]*c[0]+A[1][i]*c[1],'Usaste una columna de A en lugar de una fila.']],regla:'(A·c)ᵢ = fila i de A · c.',pista:'Fila del producto por el vector de costos.',comprobar:()=>v===A[i].reduce((s,x,k)=>s+x*c[k],0)})}}},
  'al/inversa':{tarjetas:T(['Inversa de [[a, b], [c, d]]','(1/(ad − bc))·[[d, −b], [−c, a]].'],['¿Cuándo existe la inversa?','Cuando det(A) ≠ 0.'],['A·A⁻¹ =','I, la matriz identidad.']),
    aplicaciones:{
      precios:(n,r)=>{const x=r.entero(5,40),y=r.entero(5,40),A=[[2,1],[1,3]];return prob({enunciado:`2 tortas + 1 refresco = $${2*x+y}; 1 torta + 3 refrescos = $${x+3*y}. Con la inversa de [[2, 1], [1, 3]], ¿cuánto cuesta una torta?`,v:x,dec:0,unidad:'pesos',
        pasos:[paso('Inversa',`det = 2·3 − 1·1 = 5 ; A⁻¹ = (1/5)[[3, −1], [−1, 2]]`,'Fórmula 2×2.'),final('Multiplica A⁻¹·b',`x = (3·${2*x+y} − 1·${x+3*y})/5 = ${marca(x)}`,'Primera entrada.')],
        errores:[[y,'Ese es el refresco.'],[(2*x+y)/2,'Ignoraste el refresco.']],regla:'Ax = b ⇒ x = A⁻¹b.',pista:'Primera fila de A⁻¹ por b.',comprobar:()=>(3*(2*x+y)-(x+3*y))/5===x})},
      cifrado:(n,r)=>{const p=r.entero(1,20),q=r.entero(1,20);return prob({enunciado:`Un mensaje (p, q) se cifró con [[1, 1], [1, 2]] y dio (${p+q}, ${p+2*q}). Con la inversa [[2, −1], [−1, 1]], ¿cuánto vale p?`,v:p,dec:0,
        pasos:[paso('Multiplica por la inversa',`p = 2·${p+q} − 1·${p+2*q}`,'Primera fila de A⁻¹.'),final('Calcula',marca(p),'Mensaje original.')],
        errores:[[q,'Ese es q.'],[p+q,'Ese es el número cifrado.']],regla:'Descifrar = multiplicar por la inversa.',pista:'A⁻¹ por el vector cifrado.',comprobar:()=>2*(p+q)-(p+2*q)===p})}}},
  'al/determinante':{tarjetas:T(['det [[a, b], [c, d]]','ad − bc.'],['|det(u, v)| es…','el área del paralelogramo formado por u y v.'],['Si una fila es múltiplo de otra…','el determinante vale 0.']),
    aplicaciones:{
      paralelogramo:(n,r)=>{const u=[r.entero(1,9),r.entero(-5,5)],v2=[r.entero(-5,5),r.entero(1,9)],v=Math.abs(u[0]*v2[1]-u[1]*v2[0]);return prob({enunciado:`Un panel solar tiene forma de paralelogramo con lados u = (${u.join(', ')}) y v = (${v2.join(', ')}) metros. ¿Cuál es su área?`,v,dec:0,unidad:'m²',
        pasos:[paso('Determinante',`${u[0]}·${v2[1]} − (${u[1]})·(${v2[0]}) = ${u[0]*v2[1]-u[1]*v2[0]}`,'det [u v].'),final('Valor absoluto',marca(v),'Un área no es negativa.')],
        errores:[[Math.abs(u[0]*v2[1]+u[1]*v2[0]),'Es ad − bc, no ad + bc.'],[u[0]*v2[0]+u[1]*v2[1],'Eso es el producto punto.']],regla:'Área del paralelogramo = |det(u, v)|.',pista:'ad − bc.',comprobar:()=>v===Math.abs(u[0]*v2[1]-u[1]*v2[0])})},
      triangulo:(n,r)=>{const P=[[0,0],[r.entero(2,9),r.entero(0,4)],[r.entero(0,4),r.entero(2,9)]],d=(P[1][0]-P[0][0])*(P[2][1]-P[0][1])-(P[2][0]-P[0][0])*(P[1][1]-P[0][1]),v=Math.abs(d)/2;return prob({enunciado:`Un terreno triangular tiene vértices (0, 0), (${P[1].join(', ')}) y (${P[2].join(', ')}) en hm. ¿Cuál es su área?`,v,dec:1,unidad:'hm²',
        pasos:[paso('Determinante de los lados',`${P[1][0]}·${P[2][1]} − ${P[2][0]}·${P[1][1]} = ${d}`,'Vectores desde (0, 0).'),final('Mitad del valor absoluto',`|${d}|/2 = ${marca(fmt(v,1))}`,'Triángulo = medio paralelogramo.')],
        errores:[[Math.abs(d),'Falta dividir entre 2.'],[Math.abs(d)/4,'Es la mitad, no la cuarta parte.']],regla:'Área del triángulo = |det|/2.',pista:'Medio paralelogramo.',comprobar:()=>cerca(v,Math.abs(P[1][0]*P[2][1]-P[2][0]*P[1][1])/2)})}}},
  'al/vector-magnitud':{tarjetas:T(['‖(a, b)‖ =','√(a² + b²).'],['Vector unitario de v','v/‖v‖ (misma dirección, longitud 1).'],['‖(a, b, c)‖ =','√(a² + b² + c²).']),
    aplicaciones:{
      dron:(n,r)=>{const [a,b]=r.elegir([[3,4],[6,8],[5,12],[9,12],[8,15]]),k=r.entero(1,5),v=Math.hypot(a*k,b*k);return prob({enunciado:`Un dron se desplaza ${a*k} m al este y ${b*k} m al norte. ¿A qué distancia en línea recta quedó del punto de partida?`,v,dec:2,unidad:'m',
        pasos:[paso('Vector desplazamiento',`(${a*k}, ${b*k})`,'Este y norte.'),final('Magnitud',`√(${a*k}² + ${b*k}²) = ${marca(fmt(v))}`,'Pitágoras.')],
        errores:[[a*k+b*k,'La distancia en línea recta no es la suma.'],[(a*k)**2+(b*k)**2,'Falta sacar la raíz.']],regla:'Distancia = magnitud del vector desplazamiento.',pista:'Pitágoras.',comprobar:()=>cerca(v*v,(a*k)**2+(b*k)**2)})},
      velocidad:(n,r)=>{const a=r.entero(2,12),b=r.entero(2,12),c=r.entero(1,6),v=Math.hypot(a,b,c);return prob({enunciado:`Un avión de juguete vuela con velocidad (${a}, ${b}, ${c}) m/s. ¿Cuál es su rapidez?`,v,dec:2,unidad:'m/s',
        pasos:[paso('Suma de cuadrados',`${a*a} + ${b*b} + ${c*c} = ${a*a+b*b+c*c}`,'Tres componentes.'),final('Raíz',marca(fmt(v)),'Rapidez = magnitud.')],
        errores:[[a+b+c,'La magnitud no es la suma de componentes.'],[Math.hypot(a,b),'Falta la componente vertical.']],regla:'‖v‖ = √(a² + b² + c²).',pista:'Tres componentes.',comprobar:()=>cerca(v*v,a*a+b*b+c*c)})}}},
  'al/vector-operaciones':{tarjetas:T(['u + v','Se suman componente a componente.'],['k·v','Se multiplica cada componente por k.'],['u − v','Desplazamiento de la punta de v a la punta de u.']),
    aplicaciones:{
      ruta:(n,r)=>{const d=[[r.entero(-9,9),r.entero(-9,9)],[r.entero(-9,9),r.entero(-9,9)],[r.entero(-9,9),r.entero(-9,9)]],x=d[0][0]+d[1][0]+d[2][0];return prob({enunciado:`Un repartidor hace tres tramos: (${d[0].join(', ')}), (${d[1].join(', ')}) y (${d[2].join(', ')}) km. ¿Cuál es la coordenada x de su posición final si salió del origen?`,v:x,dec:0,unidad:'km',
        pasos:[paso('Suma los vectores',`(${d.map(z=>z[0]).join(' + ')}, ${d.map(z=>z[1]).join(' + ')})`,'Componente a componente.'),final('Coordenada x',marca(x),'Primera componente.')],
        errores:[[d[0][1]+d[1][1]+d[2][1],'Esa es la coordenada y.'],[d[2][0],'Ese es solo el último tramo.']],regla:'Desplazamiento total = suma de los vectores.',pista:'Suma las x.',comprobar:()=>x===d.reduce((s,z)=>s+z[0],0)})},
      fuerza:(n,r)=>{const F=[r.entero(-20,20),r.entero(-20,20)],k=r.entero(2,4),G=[r.entero(-20,20),r.entero(-20,20)],y=k*F[1]+G[1];return prob({enunciado:`Sobre una caja actúan ${k} cuerdas iguales con fuerza (${F.join(', ')}) N y una fuerza (${G.join(', ')}) N. ¿Cuál es la componente y de la fuerza neta?`,v:y,dec:0,unidad:'N',
        pasos:[paso('Escala y suma',`${k}·(${F.join(', ')}) + (${G.join(', ')})`,'k·F + G.'),final('Componente y',`${k}·${F[1]} + ${G[1]} = ${marca(y)}`,'Segunda componente.')],
        errores:[[F[1]+G[1],'Son '+k+' cuerdas: multiplica por '+k+'.'],[k*F[0]+G[0],'Esa es la componente x.']],regla:'Fuerza neta = suma de fuerzas (con sus múltiplos).',pista:'k·F + G.',comprobar:()=>y===k*F[1]+G[1]})}}},
  'al/producto-punto':{tarjetas:T(['u · v =','u₁v₁ + u₂v₂ (+ u₃v₃).'],['u · v = 0 significa…','que u y v son perpendiculares (ortogonales).'],['u · v = ‖u‖‖v‖ cos θ','Relaciona el producto punto con el ángulo.']),
    aplicaciones:{
      trabajo:(n,r)=>{const F=[r.entero(1,20),r.entero(-10,10)],d=[r.entero(1,15),r.entero(-5,5)],v=F[0]*d[0]+F[1]*d[1];return prob({enunciado:`Una fuerza F = (${F.join(', ')}) N mueve un objeto d = (${d.join(', ')}) m. ¿Cuánto trabajo realiza? (W = F · d)`,v,dec:0,unidad:'J',
        pasos:[paso('Producto punto',`${F[0]}·${d[0]} + (${F[1]})·(${d[1]})`,'Componente a componente.'),final('Suma',marca(v),'Joules.')],
        errores:[[F[0]*d[1]-F[1]*d[0],'Eso se parece a un determinante, no al producto punto.'],[Math.hypot(...F)*Math.hypot(...d),'Falta el coseno del ángulo: usa F · d.']],regla:'Trabajo = F · d.',pista:'Suma de productos.',comprobar:()=>v===F.reduce((s,x,i)=>s+x*d[i],0)})},
      ingreso:(n,r)=>{const p=[r.entero(10,90),r.entero(10,90),r.entero(10,90)],q=[r.entero(1,20),r.entero(1,20),r.entero(1,20)],v=p[0]*q[0]+p[1]*q[1]+p[2]*q[2];return prob({enunciado:`Precios p = (${p.join(', ')}) y cantidades vendidas q = (${q.join(', ')}). ¿Cuál es el ingreso p · q?`,v,dec:0,unidad:'pesos',
        pasos:[paso('Producto punto',p.map((x,i)=>`${x}·${q[i]}`).join(' + '),'Precio por cantidad.'),final('Suma',marca(v),'Ingreso.')],
        errores:[[p.reduce((a,b)=>a+b)*q.reduce((a,b)=>a+b),'No se multiplican las sumas.'],[p[0]*q[0],'Faltan dos productos.']],regla:'Ingreso total = p · q.',pista:'Suma de precio × cantidad.',comprobar:()=>v===p.reduce((s,x,i)=>s+x*q[i],0)})}}},
  'al/angulo':{tarjetas:T(['cos θ entre u y v','(u · v)/(‖u‖‖v‖).'],['Si u · v < 0…','el ángulo es obtuso (mayor de 90°).'],['Ángulo entre vectores paralelos del mismo sentido','0°.']),
    aplicaciones:{
      rutas:(n,r)=>{const [u,w]=r.elegir([[[1,0],[1,1]],[[3,4],[4,3]],[[1,2],[2,-1]],[[2,0],[-1,1]],[[1,1],[-1,1]]]),c=(u[0]*w[0]+u[1]*w[1])/(Math.hypot(...u)*Math.hypot(...w)),v=Math.acos(c)*180/Math.PI;return prob({enunciado:`Dos caminos salen del mismo punto en las direcciones (${u.join(', ')}) y (${w.join(', ')}). ¿Qué ángulo forman (en grados)?`,v,dec:1,unidad:'°',
        pasos:[paso('cos θ',`${u[0]*w[0]+u[1]*w[1]} / (${fmt(Math.hypot(...u),3)}·${fmt(Math.hypot(...w),3)}) = ${fmt(c,4)}`,'Producto punto entre normas.'),final('θ = arccos',marca(fmt(v,1)),'Grados.')],
        errores:[[c,'Ese es el coseno, no el ángulo.'],[180-v,'Revisa el signo del producto punto.']],regla:'θ = arccos(u·v /(‖u‖‖v‖)).',pista:'Usa el producto punto.',comprobar:()=>cerca(Math.cos(v*Math.PI/180),c,1e-6)})},
      perp:(n,r)=>{const a=r.entero(1,6),b=r.entero(1,6),k=-a*r.entero(1,4),v=-a*k/b;return prob({enunciado:`Una viga sigue la dirección (${a}, ${b}) y otra la dirección (${k}, y). ¿Cuánto debe valer y para que sean perpendiculares?`,v,dec:2,
        pasos:[paso('Producto punto igual a 0',`${a}·${k} + ${b}·y = 0`,'Perpendiculares.'),final('Despeja',`y = ${-a*k}/${b} = ${marca(fmt(v))}`,'Valor de y.')],
        errores:[[a*k/b,'Revisa el signo al despejar.'],[b*k/a,'Despeja y correctamente.']],regla:'Perpendiculares ⇔ u · v = 0.',pista:'Iguala el producto punto a 0.',comprobar:()=>cerca(a*k+b*v,0)})}}},
  'al/producto-cruz':{tarjetas:T(['u × v es…','un vector perpendicular a u y a v.'],['‖u × v‖ =','el área del paralelogramo formado por u y v.'],['u × v = −(v × u)','El producto cruz no es conmutativo (cambia de signo).']),
    aplicaciones:{
      torque:(n,r)=>{const rr=[r.entero(1,5),0,0],F=[0,r.entero(1,20),0],v=rr[0]*F[1];return prob({enunciado:`Aprietas una tuerca con una llave de brazo r = (${rr.join(', ')}) m y fuerza F = (${F.join(', ')}) N. ¿Cuánto mide el torque ‖r × F‖?`,v,dec:2,unidad:'N·m',
        pasos:[paso('Producto cruz',`r × F = (0, 0, ${rr[0]}·${F[1]})`,'Solo hay componente z.'),final('Magnitud',marca(v),'Torque.')],
        errores:[[0,'r y F son perpendiculares: el torque no es 0.'],[rr[0]+F[1],'Se multiplican, no se suman.']],regla:'Torque = ‖r × F‖ = ‖r‖‖F‖ sen θ.',pista:'Perpendiculares: sen 90° = 1.',comprobar:()=>v===rr[0]*F[1]})},
      area:(n,r)=>{const u=[r.entero(1,5),r.entero(0,4),0],w=[r.entero(0,4),r.entero(1,5),0],v=Math.abs(u[0]*w[1]-u[1]*w[0]);return prob({enunciado:`Una lona tiene forma de paralelogramo con lados u = (${u.join(', ')}) m y v = (${w.join(', ')}) m. ¿Cuál es su área? (‖u × v‖)`,v,dec:2,unidad:'m²',
        pasos:[paso('Producto cruz',`u × v = (0, 0, ${u[0]*w[1]-u[1]*w[0]})`,'Componente z.'),final('Magnitud',marca(v),'Área.')],
        errores:[[u[0]*w[0]+u[1]*w[1],'Eso es el producto punto.'],[(u[0]*w[1]-u[1]*w[0])/2,'Eso sería un triángulo.']],regla:'Área del paralelogramo = ‖u × v‖.',pista:'Calcula u × v.',comprobar:()=>v===Math.abs(u[0]*w[1]-u[1]*w[0])})}}},
  'al/combinacion-lineal':{tarjetas:T(['Combinación lineal de u y v','a·u + b·v con escalares a y b.'],['¿Cómo se encuentran a y b?','Resolviendo el sistema que sale de igualar componentes.'],['Espacio generado (span)','Todas las combinaciones lineales posibles de los vectores.']),
    aplicaciones:{
      aleacion:(n,r)=>{const a=r.entero(1,6),b=r.entero(1,6),u=[2,1],w=[1,3];return prob({enunciado:`La aleación A tiene (2 kg cobre, 1 kg zinc) por lingote y la B (1, 3). Quieres (${2*a+b}, ${a+3*b}) kg de cobre y zinc. ¿Cuántos lingotes de A necesitas?`,v:a,dec:0,unidad:'lingotes',
        pasos:[paso('Plantea',`a(2, 1) + b(1, 3) = (${2*a+b}, ${a+3*b})`,'Combinación lineal.'),paso('Sistema',`2a + b = ${2*a+b} ; a + 3b = ${a+3*b}`,'Componente a componente.'),final('Resuelve',`a = ${marca(a)}, b = ${b}`,'Lingotes de A.')],
        errores:[[b,'Ese es b.'],[2*a+b,'Ese es el cobre total.']],regla:'Escribir w como a·u + b·v lleva a un sistema.',pista:'Iguala componentes.',comprobar:()=>2*a+b===u[0]*a+w[0]*b&&a+3*b===u[1]*a+w[1]*b})},
      color:(n,r)=>{const a=r.entero(1,4),b=r.entero(1,4);return prob({enunciado:`Mezclas pintura: el tono 1 aporta (rojo 3, azul 1) y el tono 2 aporta (1, 2) por cucharada. Para obtener (${3*a+b}, ${a+2*b}), ¿cuántas cucharadas del tono 2?`,v:b,dec:0,unidad:'cucharadas',
        pasos:[paso('Sistema',`3a + b = ${3*a+b} ; a + 2b = ${a+2*b}`,'Combinación lineal.'),final('Resuelve',`b = ${marca(b)}`,'Elimina a.')],
        errores:[[a,'Ese es a.'],[(a+2*b)/2,'Falta considerar el tono 1.']],regla:'Los coeficientes de la combinación salen del sistema.',pista:'Elimina a.',comprobar:()=>3*a+b===3*a+b&&a+2*b===a+2*b})}}},
  'al/independencia':{tarjetas:T(['Vectores linealmente independientes','Ninguno es combinación lineal de los otros.'],['Prueba rápida para 2 vectores en R²','Son independientes si det ≠ 0.'],['n vectores en Rⁿ son una base…','si son linealmente independientes.']),
    aplicaciones:{
      sensores:(n,r)=>{const a=r.entero(1,6),b=r.entero(1,6),c=r.entero(2,5),v=b*c/a;return prob({enunciado:`Dos sensores dan las direcciones (${a}, ${b}) y (${c}, k). ¿Para qué k las mediciones son redundantes (linealmente dependientes)?`,v,dec:2,
        pasos:[paso('Determinante cero',`${a}·k − ${b}·${c} = 0`,'Dependientes ⇔ det = 0.'),final('Despeja',`k = ${b*c}/${a} = ${marca(fmt(v))}`,'Valor crítico.')],
        errores:[[a*c/b,'Despeja k del determinante.'],[0,'Con k = 0 el determinante no es 0.']],regla:'Dos vectores en R² son dependientes si det = 0.',pista:'ad − bc = 0.',comprobar:()=>cerca(a*v-b*c,0)})},
      base:(n,r)=>{const k=r.entero(2,6),v=k;return prob({enunciado:`Un analista quiere que (1, 2, 3), (0, 1, 4) y (0, 0, k − ${k}) formen una base. ¿Para qué valor de k NO forman base?`,v,dec:0,
        pasos:[paso('Matriz triangular',`det = 1·1·(k − ${k})`,'Producto de la diagonal.'),final('No hay base si det = 0',`k = ${marca(k)}`,'Dependientes.')],
        errores:[[0,'Con k = 0 el det es '+(-k)+', no 0.'],[1,'Revisa la diagonal.']],regla:'Tres vectores de R³ son base si su determinante no es 0.',pista:'Diagonal de una triangular.',comprobar:()=>1*1*(v-k)===0})}}},
  'al/transformaciones':{tarjetas:T(['Transformación lineal','T(u + v) = T(u) + T(v) y T(cu) = cT(u).'],['Matriz de rotación de 90°','[[0, −1], [1, 0]].'],['Columnas de la matriz estándar','Son T(e₁), T(e₂), …']),
    aplicaciones:{
      rotar:(n,r)=>{const P=[r.entero(-9,9),r.entero(-9,9)],v=-P[1];return prob({enunciado:`Un videojuego rota un personaje 90° antihorario con [[0, −1], [1, 0]]. Si está en (${P.join(', ')}), ¿cuál es su nueva coordenada x?`,v,dec:0,
        pasos:[paso('Multiplica',`[[0, −1], [1, 0]]·(${P.join(', ')}) = (${-P[1]}, ${P[0]})`,'Fila por columna.'),final('Coordenada x',marca(v),'Primera entrada.')],
        errores:[[P[0],'Esa es la nueva y.'],[P[1],'Falta el signo menos.']],regla:'Rotación de 90°: (x, y) → (−y, x).',pista:'Primera fila por el vector.',comprobar:()=>v===0*P[0]-1*P[1]})},
      escalar:(n,r)=>{const k=r.entero(2,5),h=r.entero(1,4),P=[r.entero(1,9),r.entero(1,9)],v=k*P[0]+h*P[1];return prob({enunciado:`Una deformación aplica [[${k}, ${h}], [0, 1]] a un punto (${P.join(', ')}). ¿Cuál es su nueva coordenada x?`,v,dec:0,
        pasos:[paso('Primera fila por el punto',`${k}·${P[0]} + ${h}·${P[1]}`,'T(x) = Ax.'),final('Calcula',marca(v),'Nueva x.')],
        errores:[[k*P[0],'Falta el corte '+h+'·y.'],[P[1],'La y no cambia, pero se pide la x.']],regla:'La imagen de un punto es la matriz por el punto.',pista:'Fila 1 · punto.',comprobar:()=>v===k*P[0]+h*P[1]})}}},
  'al/valores-propios':{tarjetas:T(['Valor propio λ de A','Número tal que Av = λv para algún v ≠ 0.'],['Ecuación característica','det(A − λI) = 0.'],['Suma y producto de valores propios (2×2)','Suma = traza; producto = determinante.']),
    aplicaciones:{
      poblacion:(n,r)=>{const l1=r.entero(2,4),l2=r.entero(-1,1)||1,tr=l1+l2,det=l1*l2;return prob({enunciado:`Una población por edades evoluciona con una matriz de traza ${tr} y determinante ${det}. ¿Cuál es el valor propio dominante (el mayor), que da el factor de crecimiento a largo plazo?`,v:Math.max(l1,l2),dec:2,
        pasos:[paso('Ecuación característica',`λ² − ${tr}λ + ${det} = 0`,'λ² − traza·λ + det.'),final('El mayor',`λ = ${marca(Math.max(l1,l2))}`,'Factor de crecimiento.')],
        errores:[[Math.min(l1,l2),'Ese es el menor.'],[tr,'La traza es la suma de los dos.']],regla:'λ² − (traza)λ + det = 0 para 2×2.',pista:'Resuelve la cuadrática.',comprobar:()=>cerca(l1*l1-tr*l1+det,0)})},
      markov:(n,r)=>{const v=1;return prob({enunciado:`Una matriz de transición de clientes entre dos compañías tiene columnas que suman 1. ¿Qué valor propio garantiza que existe un estado estable?`,v,dec:0,
        pasos:[paso('Columnas que suman 1','(1, 1) es vector propio izquierdo con λ = 1','Propiedad de las matrices estocásticas.'),final('Valor propio',marca(1),'Estado estable: Ax = x.')],
        errores:[[0,'Con 0 todo desaparece.'],[2,'Una probabilidad no puede crecer.']],regla:'Una matriz estocástica siempre tiene λ = 1.',pista:'Ax = x.',comprobar:()=>true})}}},

  /* ---------- Cálculo diferencial ---------- */
  'cd/limites':{tarjetas:T(['Primer intento al calcular un límite','Sustituir directamente.'],['Si sale 0/0…','factoriza, simplifica o racionaliza y vuelve a sustituir.'],['El límite existe si…','los límites laterales existen y son iguales.']),
    aplicaciones:{
      promedio:(n,r)=>{const f=r.entero(1000,9000),c=r.entero(5,50),v=c;return prob({enunciado:`Producir x piezas cuesta C(x) = ${f} + ${c}x. ¿A qué valor tiende el costo promedio C(x)/x cuando x → ∞?`,v,dec:2,unidad:'pesos por pieza',
        pasos:[paso('Divide',`C(x)/x = ${f}/x + ${c}`,'Separa la fracción.'),final('Límite',`${f}/x → 0, queda ${marca(c)}`,'El costo fijo se reparte.')],
        errores:[[f+c,'El costo fijo se divide entre x.'],[0,'El costo variable no desaparece.']],regla:'k/x → 0 cuando x → ∞.',pista:'Separa en dos fracciones.',comprobar:()=>cerca((f+c*1e9)/1e9,c,1e-5)})},
      velocidad:(n,r)=>{const a=r.entero(1,5),t0=r.entero(1,5),v=2*a*t0;return prob({enunciado:`Un objeto recorre s(t) = ${a}t² metros. Calcula el límite de [s(t) − s(${t0})]/(t − ${t0}) cuando t → ${t0} (velocidad instantánea).`,v,dec:2,unidad:'m/s',
        pasos:[paso('Factoriza',`${a}(t² − ${t0*t0})/(t − ${t0}) = ${a}(t + ${t0})`,'Diferencia de cuadrados.'),final('Sustituye',`${a}(${t0} + ${t0}) = ${marca(v)}`,'Ya no hay 0/0.')],
        errores:[[a*t0*t0,'Esa es la posición, no la velocidad.'],[a*t0,'Falta el factor 2.']],regla:'Si da 0/0, simplifica antes de sustituir.',pista:'t² − a² = (t − a)(t + a).',comprobar:()=>cerca((a*(t0+1e-6)**2-a*t0*t0)/1e-6,v,1e-4)})}}},
  'cd/continuidad':{tarjetas:T(['f es continua en a si…','f(a) existe, el límite existe y lím f(x) = f(a).'],['Discontinuidad removible','El límite existe pero no coincide con f(a) (o f(a) no existe).'],['Discontinuidad de salto','Los límites laterales existen pero son distintos.']),
    aplicaciones:{
      tarifa:(n,r)=>{const a=r.entero(2,6),b=r.entero(10,30),x0=r.entero(5,20),c=r.entero(1,a-1),v=a*x0+b-c*x0;return prob({enunciado:`Una tarifa eléctrica cobra ${a}x + ${b} si x ≤ ${x0} kWh y ${c}x + k si x > ${x0}. ¿Cuánto debe valer k para que la tarifa sea continua?`,v,dec:0,
        pasos:[paso('Iguala en el punto de cambio',`${a}(${x0}) + ${b} = ${c}(${x0}) + k`,'Mismo valor por ambos lados.'),final('Despeja',`k = ${a*x0+b} − ${c*x0} = ${marca(v)}`,'Valor de k.')],
        errores:[[b,'Las pendientes cambian: k no es igual a '+b+'.'],[a*x0+b,'Falta restar '+c+'·'+x0+'.']],regla:'Continua en el cambio de regla: los dos lados dan lo mismo.',pista:'Iguala las dos reglas en x = '+x0+'.',comprobar:()=>a*x0+b===c*x0+v})},
      envio:(n,r)=>{const x0=r.entero(2,6),m=r.entero(20,60),v=m*x0;return prob({enunciado:`Un envío cuesta ${m}x pesos hasta ${x0} kg y luego k + 10(x − ${x0}). ¿Qué valor de k evita un salto en x = ${x0}?`,v,dec:0,unidad:'pesos',
        pasos:[paso('Valor por la izquierda',`${m}·${x0} = ${m*x0}`,'Primera regla.'),final('Por la derecha debe dar lo mismo',`k + 0 = ${marca(v)}`,'Sin salto.')],
        errores:[[m,'Falta multiplicar por los kg.'],[m*x0+10,'En x = '+x0+' el segundo término vale 0.']],regla:'Sin salto: límite por la izquierda = límite por la derecha = f(a).',pista:'Evalúa ambas reglas en el punto.',comprobar:()=>v===m*x0})}}},
  'cd/definicion':{tarjetas:T(['Definición de derivada','f′(a) = lím_{h→0} [f(a + h) − f(a)]/h.'],['Interpretación geométrica','Pendiente de la recta tangente en x = a.'],['Interpretación física','Razón de cambio instantánea (p. ej. velocidad).']),
    aplicaciones:{
      costo:(n,r)=>{const a=r.entero(1,5),b=r.entero(10,50),x=r.entero(10,100),v=2*a*x+b;return prob({enunciado:`El costo de producir x unidades es C(x) = ${a}x² + ${b}x. Con la definición de derivada, ¿cuál es el costo marginal C′(${x})?`,v,dec:0,unidad:'pesos por unidad',
        pasos:[paso('Cociente de diferencias',`[C(${x} + h) − C(${x})]/h = ${2*a*x}+${a}h + ${b}`,'Expande y cancela.'),final('h → 0',`C′(${x}) = ${marca(v)}`,'Costo marginal.')],
        errores:[[a*x*x+b*x,'Ese es el costo, no el marginal.'],[a*x+b,'Falta el 2 de la derivada de x².']],regla:'Costo marginal = C′(x).',pista:'(x + h)² = x² + 2xh + h².',comprobar:()=>cerca(derivNum(t=>a*t*t+b*t,x),v,1e-4)})},
      pendiente:(n,r)=>{const a=r.entero(1,4),x=r.entero(-4,4),v=3*a*x*x;return prob({enunciado:`Una pista de patinaje tiene perfil y = ${a}x³. ¿Cuál es la pendiente en x = ${x}?`,v,dec:0,
        pasos:[paso('Derivada por definición',`[${a}(x + h)³ − ${a}x³]/h → ${3*a}x²`,'Desarrolla el cubo.'),final('Evalúa',`${3*a}(${x})² = ${marca(v)}`,'Pendiente.')],
        errores:[[a*x**3,'Esa es la altura.'],[3*a*x,'La derivada de x³ es 3x².']],regla:'Pendiente de la tangente = f′(a).',pista:'(x + h)³.',comprobar:()=>cerca(derivNum(t=>a*t**3,x),v,1e-4)})}}},
  'cd/derivada-polinomio':{tarjetas:T(['Regla de la potencia','d/dx xⁿ = n·xⁿ⁻¹.'],['Derivada de una constante','0.'],['Derivada de una suma','La suma de las derivadas.']),
    aplicaciones:{
      vel:(n,r)=>{const a=r.entero(1,5),b=r.entero(1,20),t=r.entero(1,8),v=2*a*t+b;return prob({enunciado:`Un auto avanza s(t) = ${a}t² + ${b}t metros. ¿Cuál es su velocidad en t = ${t} s?`,v,dec:0,unidad:'m/s',
        pasos:[paso('Deriva',`s′(t) = ${2*a}t + ${b}`,'Regla de la potencia.'),final('Evalúa',`${2*a}(${t}) + ${b} = ${marca(v)}`,'Velocidad.')],
        errores:[[a*t*t+b*t,'Esa es la posición.'],[a*t+b,'d/dt t² = 2t.']],regla:'Velocidad = derivada de la posición.',pista:'Deriva término a término.',comprobar:()=>cerca(derivNum(x=>a*x*x+b*x,t),v,1e-4)})},
      ingreso:(n,r)=>{const p=r.entero(100,300),c=r.entero(1,4),x=r.entero(5,40),v=p-2*c*x;return prob({enunciado:`El ingreso por vender x artículos es R(x) = ${p}x − ${c}x². ¿Cuál es el ingreso marginal R′(${x})?`,v,dec:0,unidad:'pesos por artículo',
        pasos:[paso('Deriva',`R′(x) = ${p} − ${2*c}x`,'Potencia.'),final('Evalúa',`${p} − ${2*c}(${x}) = ${marca(v)}`,'Ingreso marginal.')],
        errores:[[p*x-c*x*x,'Ese es el ingreso.'],[p-c*x,'d/dx x² = 2x.']],regla:'Marginal = derivada.',pista:'Deriva cada término.',comprobar:()=>cerca(derivNum(y=>p*y-c*y*y,x),v,1e-4)})}}},
  'cd/producto':{tarjetas:T(['Regla del producto','(fg)′ = f′g + fg′.'],['Error común','(fg)′ ≠ f′·g′.'],['Úsala cuando…','la función es un producto de dos funciones de x.']),
    aplicaciones:{
      ingreso:(n,r)=>{const a=r.entero(100,200),b=r.entero(1,5),x=r.entero(5,30),v=a-2*b*x;return prob({enunciado:`El precio de un producto es p(x) = ${a} − ${b}x y se venden x unidades: R(x) = x·p(x). Con la regla del producto, ¿cuánto vale R′(${x})?`,v,dec:0,
        pasos:[paso('f = x, g = p(x)',`R′ = 1·(${a} − ${b}x) + x·(−${b})`,'f′g + fg′.'),final('Evalúa',`${a-b*x} − ${b*x} = ${marca(v)}`,'Ingreso marginal.')],
        errores:[[-b,'(fg)′ no es f′·g′.'],[a-b*x,'Falta el término f·g′.']],regla:'(fg)′ = f′g + fg′.',pista:'f = x, g = precio.',comprobar:()=>cerca(derivNum(y=>y*(a-b*y),x),v,1e-4)})},
      area:(n,r)=>{const w=r.entero(2,10),dw=r.entero(1,3),l=r.entero(5,20),dl=r.entero(1,3),v=dw*l+w*dl;return prob({enunciado:`Un rectángulo crece: ancho ${w} cm (aumenta ${dw} cm/s) y largo ${l} cm (aumenta ${dl} cm/s). ¿A qué ritmo crece su área en ese instante?`,v,dec:0,unidad:'cm²/s',
        pasos:[paso('A = ancho·largo',`A′ = ancho′·largo + ancho·largo′`,'Regla del producto.'),final('Sustituye',`${dw}·${l} + ${w}·${dl} = ${marca(v)}`,'cm²/s.')],
        errores:[[dw*dl,'(fg)′ no es f′·g′.'],[w*l,'Esa es el área, no su ritmo.']],regla:'(fg)′ = f′g + fg′.',pista:'Dos términos.',comprobar:()=>cerca(((w+dw*1e-6)*(l+dl*1e-6)-w*l)/1e-6,v,1e-3)})}}},
  'cd/cociente':{tarjetas:T(['Regla del cociente','(f/g)′ = (f′g − fg′)/g².'],['Orden del numerador','f′g − fg′ (primero la derivada del de arriba).'],['El denominador','Se eleva al cuadrado: g².']),
    aplicaciones:{
      promedio:(n,r)=>{const f=r.entero(500,3000),c=r.entero(5,30),x=r.entero(10,100),v=-f/(x*x);return prob({enunciado:`El costo promedio es A(x) = (${f} + ${c}x)/x. Con la regla del cociente, ¿cuánto vale A′(${x})? (4 decimales)`,v,dec:4,
        pasos:[paso('Cociente',`A′ = [${c}·x − (${f} + ${c}x)·1]/x²`,'(f′g − fg′)/g².'),final('Simplifica y evalúa',`−${f}/${x}² = ${marca(fmt(v,4))}`,'Baja al producir más.')],
        errores:[[c,'Esa es la derivada solo del numerador.'],[f/(x*x),'El signo es negativo: el promedio baja.']],regla:'(f/g)′ = (f′g − fg′)/g².',pista:'f = '+f+' + '+c+'x, g = x.',comprobar:()=>cerca(derivNum(y=>(f+c*y)/y,x),v,1e-6)})},
      conc:(n,r)=>{const a=r.entero(2,9),b=r.entero(1,9),t=r.entero(1,5),v=a*(b-t*t)/((t*t+b)**2);return prob({enunciado:`La concentración de un medicamento es C(t) = ${a}t/(t² + ${b}). ¿A qué ritmo cambia en t = ${t} h? (4 decimales)`,v,dec:4,
        pasos:[paso('Cociente',`C′ = [${a}(t² + ${b}) − ${a}t·2t]/(t² + ${b})²`,'(f′g − fg′)/g².'),final('Evalúa',`${a}(${b} − ${t*t})/${(t*t+b)**2} = ${marca(fmt(v,4))}`,'Ritmo.')],
        errores:[[a/(2*t),'No se derivan por separado.'],[-v,'Revisa el orden f′g − fg′.']],regla:'(f/g)′ = (f′g − fg′)/g².',pista:'g = t² + b.',comprobar:()=>cerca(derivNum(y=>a*y/(y*y+b),t),v,1e-6)})}}},
  'cd/cadena':{tarjetas:T(['Regla de la cadena','(f(g(x)))′ = f′(g(x))·g′(x).'],['Con potencias','d/dx [g(x)]ⁿ = n[g(x)]ⁿ⁻¹·g′(x).'],['Idea','Deriva «la de afuera» y multiplica por la derivada de «la de adentro».']),
    aplicaciones:{
      globo:(n,r)=>{const rr=r.entero(2,10),dr=r.entero(1,3),v=4*Math.PI*rr*rr*dr;return prob({enunciado:`Un globo esférico se infla: su radio crece ${dr} cm/s. ¿Qué tan rápido crece su volumen V = (4/3)πr³ cuando r = ${rr} cm?`,v,dec:2,unidad:'cm³/s',
        pasos:[paso('Cadena',`dV/dt = 4πr²·dr/dt`,'Deriva r³ y multiplica por dr/dt.'),final('Sustituye',`4π(${rr})²(${dr}) = ${marca(fmt(v))}`,'cm³/s.')],
        errores:[[4/3*Math.PI*rr**3,'Ese es el volumen.'],[4*Math.PI*rr*rr,'Falta multiplicar por dr/dt.']],regla:'Cadena: dV/dt = dV/dr · dr/dt.',pista:'Deriva respecto al tiempo.',comprobar:()=>cerca((4/3*Math.PI*((rr+dr*1e-6)**3-rr**3))/1e-6,v,1e-3)})},
      raiz:(n,r)=>{const a=r.entero(1,6),b=r.entero(1,9),x=r.entero(0,6),u=a*x+b,v=a/(2*Math.sqrt(u));return prob({enunciado:`La rapidez de una ola es v(x) = √(${a}x + ${b}). ¿Cuánto vale v′(${x})? (4 decimales)`,v,dec:4,
        pasos:[paso('Cadena',`v′ = ${a}/(2√(${a}x + ${b}))`,'(√u)′ = u′/(2√u).'),final('Evalúa',`${a}/(2√${u}) = ${marca(fmt(v,4))}`,'Ritmo.')],
        errores:[[1/(2*Math.sqrt(u)),'Falta multiplicar por la derivada de adentro.'],[a*Math.sqrt(u),'Revisa la derivada de la raíz.']],regla:'(√u)′ = u′/(2√u).',pista:'u = '+a+'x + '+b+'.',comprobar:()=>cerca(derivNum(y=>Math.sqrt(a*y+b),x),v,1e-6)})}}},
  'cd/trascendentes':{tarjetas:T(['d/dx sen x y cos x','cos x y −sen x.'],['d/dx eˣ y ln x','eˣ y 1/x.'],['d/dx e^{kx}','k·e^{kx}.']),
    aplicaciones:{
      poblacion:(n,r)=>{const P0=r.entero(1,9)*1000,k=r.elegir([0.02,0.03,0.05]),t=r.entero(1,10),v=P0*k*Math.exp(k*t);return prob({enunciado:`Una ciudad tiene P(t) = ${P0}·e^{${k}t} habitantes. ¿A qué ritmo crece en t = ${t} años? (2 decimales)`,v,dec:2,unidad:'hab/año',
        pasos:[paso('Deriva',`P′(t) = ${P0}·${k}·e^{${k}t}`,'(e^{kt})′ = k e^{kt}.'),final('Evalúa',marca(fmt(v)),'Habitantes por año.')],
        errores:[[P0*Math.exp(k*t),'Esa es la población, no el ritmo.'],[P0*k,'Falta e^{kt}.']],regla:'d/dt e^{kt} = k e^{kt}.',pista:'Cadena con kt.',comprobar:()=>cerca(derivNum(y=>P0*Math.exp(k*y),t),v,1e-4)})},
      resorte:(n,r)=>{const A=r.entero(2,10),w=r.entero(1,4),t=r.elegir([0,0.5,1,1.5]),v=-A*w*Math.sin(w*t);return prob({enunciado:`Un resorte oscila con x(t) = ${A}cos(${w}t) cm. ¿Cuál es su velocidad en t = ${t} s? (2 decimales)`,v,dec:2,unidad:'cm/s',
        pasos:[paso('Deriva',`x′(t) = −${A*w}sen(${w}t)`,'(cos u)′ = −sen u·u′.'),final('Evalúa',marca(fmt(v)),'Velocidad.')],
        errores:[[A*w*Math.sin(w*t),'La derivada del coseno lleva signo menos.'],[-A*Math.sin(w*t),'Falta multiplicar por '+w+'.']],regla:'(cos kt)′ = −k sen kt.',pista:'Cadena.',comprobar:()=>cerca(derivNum(y=>A*Math.cos(w*y),t),v,1e-4)})}}},
  'cd/implicita':{tarjetas:T(['Derivación implícita','Deriva ambos lados respecto a x tratando y como función de x.'],['d/dx (y²)','2y·y′ (regla de la cadena).'],['Al final…','despeja y′.']),
    aplicaciones:{
      escalera:(n,r)=>{const [a,b,c]=r.elegir([[3,4,5],[6,8,10],[5,12,13]]),v=-a/b;return prob({enunciado:`Una escalera de ${c} m cumple x² + y² = ${c*c}. Con x = ${a} m y y = ${b} m, ¿cuánto vale dy/dx? (2 decimales)`,v,dec:2,
        pasos:[paso('Deriva implícitamente',`2x + 2y·y′ = 0`,'y depende de x.'),final('Despeja',`y′ = −x/y = −${a}/${b} = ${marca(fmt(v))}`,'Pendiente.')],
        errores:[[a/b,'Falta el signo menos.'],[-b/a,'Es −x/y.']],regla:'Deriva y como función de x y despeja y′.',pista:'2x + 2yy′ = 0.',comprobar:()=>cerca(v,-a/b)})},
      curva:(n,r)=>{const x=r.entero(1,4),y=r.entero(1,4),k=x*y,v=-y/x;return prob({enunciado:`Una lente tiene el perfil xy = ${k}. ¿Cuál es la pendiente en (${x}, ${y})? (2 decimales)`,v,dec:2,
        pasos:[paso('Producto implícito',`y + x·y′ = 0`,'Regla del producto.'),final('Despeja',`y′ = −y/x = ${marca(fmt(v))}`,'Pendiente.')],
        errores:[[y/x,'Falta el signo.'],[-x/y,'Es −y/x.']],regla:'(xy)′ = y + xy′.',pista:'Deriva el producto.',comprobar:()=>cerca(derivNum(t=>k/t,x),v,1e-5)})}}},
  'cd/razon-cambio':{tarjetas:T(['Razones relacionadas','Relaciona las variables con una ecuación y deriva respecto al tiempo.'],['Paso clave','Sustituye los valores DESPUÉS de derivar.'],['Unidades','dV/dt se mide en unidades de V por unidad de tiempo.']),
    procedimientos:{
      cubo:(n,r)=>{const x=r.entero(1,6),k=r.entero(1,5),v=3*x*x*k;return prob({enunciado:`Si y = x³ y dx/dt = ${k}, ¿cuánto vale dy/dt cuando x = ${x}?`,v,dec:0,
        pasos:[paso('Deriva respecto a t',`dy/dt = 3x²·dx/dt`,'Regla de la cadena.'),final('Sustituye',`3(${x})²(${k}) = ${marca(v)}`,'Después de derivar.')],
        errores:[[x**3*k,'Primero deriva, luego sustituye.'],[3*x*x,'Falta multiplicar por dx/dt.']],regla:'dy/dt = (dy/dx)·(dx/dt).',pista:'Cadena.',comprobar:()=>cerca(derivNum(t=>(x+k*t)**3,0),v,1e-4)})},
      producto:(n,r)=>{const x=r.entero(1,9),y=r.entero(1,9),dx=r.entero(1,4),dy=r.entero(1,4),v=dx*y+x*dy;return prob({enunciado:`Si z = x·y, con x = ${x}, y = ${y}, dx/dt = ${dx} y dy/dt = ${dy}, ¿cuánto vale dz/dt?`,v,dec:0,
        pasos:[paso('Producto',`dz/dt = dx/dt·y + x·dy/dt`,'Regla del producto.'),final('Sustituye',`${dx}·${y} + ${x}·${dy} = ${marca(v)}`,'Ritmo de z.')],
        errores:[[dx*dy,'La derivada de un producto no es el producto de derivadas.'],[x*y,'Ese es z.']],regla:'(xy)′ = x′y + xy′.',pista:'Regla del producto con t.',comprobar:()=>v===dx*y+x*dy})}},
    basicos:{
      perimetro:(n,r)=>{const k=r.entero(1,9),v=4*k;return prob({enunciado:`El lado de un cuadrado crece a ${k} cm/s. ¿A qué ritmo crece su perímetro P = 4x?`,v,dec:0,unidad:'cm/s',
        pasos:[paso('Deriva respecto al tiempo',`dP/dt = 4·dx/dt`,'La constante sale.'),final('Sustituye',`4·${k} = ${marca(v)}`,'cm/s.')],
        errores:[[k,'Falta multiplicar por 4.'],[k*k,'P es lineal en x.']],regla:'Si P = 4x, dP/dt = 4·dx/dt.',pista:'Deriva P = 4x.',comprobar:()=>v===4*k})},
      circ:(n,r)=>{const k=r.entero(1,6),v=2*Math.PI*k;return prob({enunciado:`El radio de una mancha circular crece a ${k} cm/min. ¿A qué ritmo crece su perímetro C = 2πr? (2 decimales)`,v,dec:2,unidad:'cm/min',
        pasos:[paso('Deriva',`dC/dt = 2π·dr/dt`,'Constante por la derivada.'),final('Sustituye',`2π·${k} = ${marca(fmt(v))}`,'cm/min.')],
        errores:[[k,'Falta el 2π.'],[Math.PI*k,'Es 2π, no π.']],regla:'C = 2πr ⇒ dC/dt = 2π dr/dt.',pista:'Deriva respecto a t.',comprobar:()=>cerca(v,2*Math.PI*k)})}}},
  'cd/maximos':{tarjetas:T(['Punto crítico','Donde f′(x) = 0 o f′ no existe.'],['Prueba de la segunda derivada','f′′ > 0: mínimo local; f′′ < 0: máximo local.'],['Extremos absolutos en [a, b]','Compara f en los puntos críticos y en los extremos a y b.']),
    aplicaciones:{
      altura:(n,r)=>{const v0=r.entero(2,8)*5,h0=r.entero(0,20),t=v0/10,v=h0+v0*t-5*t*t;return prob({enunciado:`Una pelota sigue h(t) = −5t² + ${v0}t + ${h0} m. ¿Cuál es su altura máxima?`,v,dec:2,unidad:'m',
        pasos:[paso('Derivada igual a cero',`h′(t) = −10t + ${v0} = 0 → t = ${t}`,'Punto crítico.'),final('Evalúa',`h(${t}) = ${marca(fmt(v))}`,'Máximo (h′′ = −10 < 0).')],
        errores:[[t,'Ese es el tiempo, no la altura.'],[h0+v0*t,'Falta el término −5t².']],regla:'El máximo está donde la derivada vale 0 y la segunda es negativa.',pista:'h′(t) = 0.',comprobar:()=>cerca(-10*t+v0,0)})},
      ganancia:(n,r)=>{const a=r.entero(1,5),b=r.entero(50,200)*2*a/2|0,c=r.entero(100,500),x=b/(2*a),v=-a*x*x+b*x-c;return prob({enunciado:`La ganancia por vender x productos es G(x) = −${a}x² + ${b}x − ${c}. ¿Cuál es la ganancia máxima?`,v,dec:2,unidad:'pesos',
        pasos:[paso('G′(x) = 0',`−${2*a}x + ${b} = 0 → x = ${fmt(x)}`,'Punto crítico.'),final('Evalúa',`G(${fmt(x)}) = ${marca(fmt(v))}`,'Máximo (G′′ < 0).')],
        errores:[[x,'Esa es la cantidad, no la ganancia.'],[b*x,'Faltan los otros términos.']],regla:'Ganancia máxima: G′(x) = 0 con G′′ < 0.',pista:'Deriva e iguala a 0.',comprobar:()=>cerca(-2*a*x+b,0)})}}},
  'cd/optimizacion':{tarjetas:T(['Pasos de un problema de optimización','Variables → función objetivo → restricción → una variable → derivar → comprobar.'],['La restricción sirve para…','dejar la función objetivo en una sola variable.'],['Siempre comprueba…','que el punto crítico es máximo o mínimo y que tiene sentido en el contexto.']),
    procedimientos:{
      minimo:(n,r)=>{const k=r.entero(1,9),a=k*k,v=2*k;return prob({enunciado:`Encuentra el valor mínimo de f(x) = x + ${a}/x para x > 0.`,v,dec:2,
        pasos:[paso('Deriva e iguala a 0',`f′(x) = 1 − ${a}/x² = 0 → x = ${k}`,'Punto crítico positivo.'),final('Evalúa',`f(${k}) = ${k} + ${a}/${k} = ${marca(v)}`,'Mínimo (f′′ > 0).')],
        errores:[[k,'Ese es el x del mínimo, no el valor mínimo.'],[a,'Evalúa f en el punto crítico.']],regla:'Optimiza: deriva, iguala a 0 y evalúa.',pista:'f′(x) = 1 − a/x².',comprobar:()=>cerca(k+a/k,v)&&k+a/k<=k+0.1+a/(k+0.1)})},
      cuadrado:(n,r)=>{const P=4*r.entero(3,30),v=(P/4)**2;return prob({enunciado:`De todos los rectángulos de perímetro ${P}, ¿cuál es el área máxima?`,v,dec:0,
        pasos:[paso('Área en una variable',`A(x) = x(${P/2} − x)`,'Usa el perímetro.'),paso('A′(x) = 0',`${P/2} − 2x = 0 → x = ${P/4}`,'Cuadrado.'),final('Evalúa',`${P/4}² = ${marca(v)}`,'Área máxima.')],
        errores:[[P,'Ese es el perímetro.'],[(P/2)**2,'Cada lado es P/4, no P/2.']],regla:'Con perímetro fijo, el área máxima es la del cuadrado.',pista:'A(x) = x(P/2 − x).',comprobar:()=>v===(P/4)*(P/2-P/4)})}},
    basicos:{
      parabola:(n,r)=>{const a=r.entero(1,5),b=2*a*r.entero(1,9),v=b/(2*a);return prob({enunciado:`¿En qué x alcanza su máximo f(x) = −${a}x² + ${b}x?`,v,dec:2,
        pasos:[paso('Deriva e iguala a 0',`f′(x) = −${2*a}x + ${b} = 0`,'Punto crítico.'),final('Despeja',`x = ${marca(fmt(v))}`,'Máximo (f′′ < 0).')],
        errores:[[b,'Despeja x: divide entre '+2*a+'.'],[-v,'Revisa el signo.']],regla:'Máximo de −ax² + bx en x = b/(2a).',pista:'f′(x) = 0.',comprobar:()=>cerca(-2*a*v+b,0)})},
      producto:(n,r)=>{const S=2*r.entero(5,50),v=S*S/4;return prob({enunciado:`Dos números positivos suman ${S}. ¿Cuál es el mayor producto posible?`,v,dec:0,
        pasos:[paso('Producto en una variable',`P(x) = x(${S} − x)`,'Usa la restricción.'),paso('P′(x) = 0',`${S} − 2x = 0 → x = ${S/2}`,'Punto crítico.'),final('Evalúa',`${S/2}·${S/2} = ${marca(v)}`,'Producto máximo.')],
        errores:[[S,'Esa es la suma.'],[S/2,'Ese es cada número.']],regla:'Con suma fija, el producto es máximo cuando los números son iguales.',pista:'P(x) = x(S − x).',comprobar:()=>v===(S/2)**2})}}},
  'cd/lhopital':{tarjetas:T(['Regla de L’Hôpital','Si lím f/g da 0/0 o ∞/∞, lím f/g = lím f′/g′.'],['Antes de aplicarla…','comprueba que el límite es indeterminado.'],['Error común','Derivar el cociente con la regla del cociente: se derivan arriba y abajo por separado.']),
    aplicaciones:{
      continuo:(n,r)=>{const k=r.elegir([0.05,0.1,0.08,0.12]),v=Math.exp(k);return prob({enunciado:`Con interés del ${k*100} % capitalizado n veces al año, el factor anual es (1 + ${k}/n)ⁿ. Usa L’Hôpital (con ln) para calcular el límite cuando n → ∞. (4 decimales)`,v,dec:4,
        pasos:[paso('Aplica ln',`ln L = lím n·ln(1 + ${k}/n) = lím ln(1 + ${k}/n)/(1/n)`,'Forma 0/0.'),paso('L’Hôpital','= '+k,'Deriva arriba y abajo.'),final('Exponencial',`L = e^{${k}} = ${marca(fmt(v,4))}`,'Interés continuo.')],
        errores:[[1+k,'Eso es capitalizar una vez al año.'],[1,'(1 + k/n)ⁿ no tiende a 1.']],regla:'Formas 1^∞: toma ln y usa L’Hôpital.',pista:'ln L = k.',comprobar:()=>cerca((1+k/1e7)**1e7,v,1e-6)})},
      ratio:(n,r)=>{const a=r.entero(2,9),b=r.entero(2,9),v=a/b;return prob({enunciado:`Dos procesos crecen como ${a}ln(x) y ${b}ln(x) + 1. ¿A qué tiende el cociente ${a}ln x / (${b}ln x + 1) cuando x → ∞? (con L’Hôpital)`,v,dec:4,
        pasos:[paso('Forma ∞/∞','Deriva arriba y abajo',`(${a}/x)/(${b}/x)`),final('Simplifica',`${a}/${b} = ${marca(fmt(v,4))}`,'Límite.')],
        errores:[[0,'Ambos crecen al mismo ritmo.'],[a,'Divide entre la derivada de abajo.']],regla:'L’Hôpital en ∞/∞: lím f′/g′.',pista:'Deriva ln x.',comprobar:()=>cerca(a*Math.log(1e300)/(b*Math.log(1e300)+1),v,1e-2)})}}},

  /* ---------- Cálculo integral ---------- */
  'ci/antiderivada':{tarjetas:T(['∫xⁿ dx','xⁿ⁺¹/(n + 1) + C (n ≠ −1).'],['∫(1/x) dx','ln|x| + C.'],['¿Por qué + C?','Porque la derivada de una constante es 0: hay infinitas antiderivadas.']),
    aplicaciones:{
      posicion:(n,r)=>{const a=r.entero(1,6),b=r.entero(0,10),s0=r.entero(0,50),T=r.entero(1,6),v=a*T*T/2+b*T+s0;return prob({enunciado:`Un ciclista tiene velocidad v(t) = ${a}t + ${b} m/s y parte de s(0) = ${s0} m. ¿Dónde está en t = ${T} s?`,v,dec:2,unidad:'m',
        pasos:[paso('Antiderivada',`s(t) = ${a}t²/2 + ${b}t + C`,'Integra la velocidad.'),paso('Condición inicial',`C = ${s0}`,'s(0) = '+s0+'.'),final('Evalúa',`s(${T}) = ${marca(fmt(v))}`,'Posición.')],
        errores:[[a*T+b,'Esa es la velocidad.'],[a*T*T/2+b*T,'Falta la posición inicial.']],regla:'Posición = antiderivada de la velocidad + condición inicial.',pista:'s(0) fija la C.',comprobar:()=>cerca(simpson(t=>a*t+b,0,T)+s0,v)})},
      costo:(n,r)=>{const m=r.entero(5,30),k=r.entero(1,4),f=r.entero(100,900),x=r.entero(10,50),v=m*x+k*x*x/2+f;return prob({enunciado:`El costo marginal es C′(x) = ${m} + ${k}x y el costo fijo es $${f}. ¿Cuánto cuesta producir ${x} unidades?`,v,dec:2,unidad:'pesos',
        pasos:[paso('Integra',`C(x) = ${m}x + ${k}x²/2 + C₀`,'Antiderivada.'),paso('Costo fijo',`C₀ = ${f}`,'C(0).'),final('Evalúa',`C(${x}) = ${marca(fmt(v))}`,'Costo.')],
        errores:[[m+k*x,'Ese es el marginal.'],[m*x+k*x*x/2,'Falta el costo fijo.']],regla:'Costo total = ∫ costo marginal + costo fijo.',pista:'C(0) = costo fijo.',comprobar:()=>cerca(simpson(t=>m+k*t,0,x)+f,v)})}}},
  'ci/definida':{tarjetas:T(['Teorema Fundamental','∫ₐᵇ f(x) dx = F(b) − F(a), con F′ = f.'],['∫ₐᵇ f para f ≥ 0','Área bajo la curva entre a y b.'],['∫ₐᵃ f(x) dx','0.']),
    aplicaciones:{
      distancia:(n,r)=>{const a=r.entero(1,4),b=r.entero(1,10),T=r.entero(1,6),v=a*T*T/2+b*T;return prob({enunciado:`Un tren acelera con v(t) = ${a}t + ${b} m/s. ¿Qué distancia recorre de t = 0 a t = ${T} s?`,v,dec:2,unidad:'m',
        pasos:[paso('Plantea',`∫₀^${T} (${a}t + ${b}) dt`,'Distancia = integral de la velocidad.'),final('Teorema Fundamental',`${a}(${T})²/2 + ${b}(${T}) = ${marca(fmt(v))}`,'F(b) − F(a).')],
        errores:[[a*T+b,'Esa es la velocidad final.'],[(a*T+b)*T,'La velocidad no es constante.']],regla:'Distancia = ∫ velocidad.',pista:'Antiderivada y evalúa.',comprobar:()=>cerca(simpson(t=>a*t+b,0,T),v)})},
      agua:(n,r)=>{const a=r.entero(1,5),T=r.entero(2,8),v=a*T**3/3;return prob({enunciado:`El agua entra a un tanque a razón de r(t) = ${a}t² litros/min. ¿Cuántos litros entran en los primeros ${T} minutos?`,v,dec:2,unidad:'L',
        pasos:[paso('Plantea',`∫₀^${T} ${a}t² dt`,'Total = integral de la tasa.'),final('Evalúa',`${a}(${T})³/3 = ${marca(fmt(v))}`,'Litros.')],
        errores:[[a*T*T,'Esa es la tasa final.'],[a*T**3,'Falta dividir entre 3.']],regla:'Cantidad acumulada = ∫ tasa.',pista:'∫t² = t³/3.',comprobar:()=>cerca(simpson(t=>a*t*t,0,T),v)})}}},
  'ci/sustitucion':{tarjetas:T(['Sustitución u = g(x)','∫f(g(x))g′(x) dx = ∫f(u) du.'],['¿Qué elegir como u?','La función de adentro, cuya derivada aparece (salvo constante).'],['En una integral definida…','cambia también los límites a u, o regresa a x antes de evaluar.']),
    aplicaciones:{
      flujo:(n,r)=>{const T=r.entero(1,3),v=((T*T+1)**3-1)/3;return prob({enunciado:`El caudal de un río sube como q(t) = 2t(t² + 1)² m³/s. ¿Cuánta agua pasa de t = 0 a t = ${T}? (2 decimales)`,v,dec:2,unidad:'m³',
        pasos:[paso('u = t² + 1',`du = 2t dt; límites 1 → ${T*T+1}`,'Sustitución.'),final('Integra',`∫₁^${T*T+1} u² du = (${T*T+1}³ − 1)/3 = ${marca(fmt(v))}`,'m³.')],
        errores:[[(T*T+1)**3/3,'Falta restar el valor en el límite inferior.'],[(T*T+1)**2,'∫u² = u³/3.']],regla:'∫f(g)g′ dx = ∫f(u) du.',pista:'u = t² + 1.',comprobar:()=>cerca(simpson(t=>2*t*(t*t+1)**2,0,T),v)})},
      enfriamiento:(n,r)=>{const k=r.elegir([1,2]),T=r.entero(1,3),v=(1-Math.exp(-k*T))/k*10;return prob({enunciado:`Un café pierde calor a razón de 10e^{−${k}t} kJ/min. ¿Cuánto calor pierde en los primeros ${T} minutos? (2 decimales)`,v,dec:2,unidad:'kJ',
        pasos:[paso('u = −'+k+'t',`∫10e^{−${k}t} dt = −(10/${k})e^{−${k}t}`,'du = −'+k+' dt.'),final('Evalúa',`(10/${k})(1 − e^{−${k*T}}) = ${marca(fmt(v))}`,'kJ.')],
        errores:[[10*(1-Math.exp(-k*T)),'Falta dividir entre '+k+'.'],[10*Math.exp(-k*T),'Esa es la tasa final.']],regla:'∫e^{ax} dx = e^{ax}/a + C.',pista:'u = −kt.',comprobar:()=>cerca(simpson(t=>10*Math.exp(-k*t),0,T),v)})}}},
  'ci/partes':{tarjetas:T(['Integración por partes','∫u dv = uv − ∫v du.'],['Regla LIATE para elegir u','Logarítmica, Inversa trig., Algebraica, Trigonométrica, Exponencial.'],['Úsala cuando…','hay un producto de funciones de distinto tipo (x·eˣ, x·sen x, ln x).']),
    aplicaciones:{
      ingreso:(n,r)=>{const T=r.entero(1,4),v=1-(T+1)*Math.exp(-T);return prob({enunciado:`Las ventas de una app nueva siguen v(t) = t·e^{−t} miles por mes. ¿Cuántos miles de descargas hay en los primeros ${T} meses? (4 decimales)`,v,dec:4,unidad:'miles',
        pasos:[paso('u = t, dv = e^{−t} dt',`∫te^{−t} dt = −te^{−t} − e^{−t}`,'Por partes.'),final('Evalúa de 0 a '+T,`1 − ${T+1}e^{−${T}} = ${marca(fmt(v,4))}`,'Miles.')],
        errores:[[T*Math.exp(-T),'Esa es la tasa al final.'],[1-Math.exp(-T),'Falta el término −te^{−t}.']],regla:'∫u dv = uv − ∫v du.',pista:'u = t.',comprobar:()=>cerca(simpson(t=>t*Math.exp(-t),0,T),v)})},
      log:(n,r)=>{const a=r.entero(2,6),v=a*Math.log(a)-a+1;return prob({enunciado:`La energía acumulada de un proceso es ∫₁^${a} ln x dx. ¿Cuánto vale? (4 decimales)`,v,dec:4,
        pasos:[paso('u = ln x, dv = dx',`∫ln x dx = x ln x − x`,'Por partes.'),final('Evalúa',`${a}ln ${a} − ${a} + 1 = ${marca(fmt(v,4))}`,'F(a) − F(1).')],
        errores:[[1/a,'La derivada de ln x no es la integral.'],[a*Math.log(a),'Falta − x.']],regla:'∫ln x dx = x ln x − x + C.',pista:'u = ln x.',comprobar:()=>cerca(simpson(Math.log,1,a),v)})}}},
  'ci/fracciones-parciales':{tarjetas:T(['Fracciones parciales','Descomponer P/Q en sumas de fracciones simples (grado P < grado Q).'],['Factor lineal (x − a)','Aporta A/(x − a).'],['∫A/(x − a) dx','A·ln|x − a| + C.']),
    aplicaciones:{
      reaccion:(n,r)=>{const a=r.entero(1,3),b=a+r.entero(1,3),T=r.entero(1,4),v=(Math.log((T+a)/a)-Math.log((T+b)/b))/(b-a);return prob({enunciado:`En una reacción química el tiempo cumple t = ∫₀^${T} dx/((x + ${a})(x + ${b})). Calcula el valor. (4 decimales)`,v,dec:4,
        pasos:[paso('Descompón',`1/((x+${a})(x+${b})) = (1/${b-a})[1/(x+${a}) − 1/(x+${b})]`,'Fracciones parciales.'),final('Integra',`(1/${b-a})[ln((x+${a})/(x+${b}))]₀^${T} = ${marca(fmt(v,4))}`,'Logaritmos.')],
        errores:[[Math.log((T+a)/a),'Falta el segundo término y el factor 1/'+(b-a)+'.'],[T/(a*b),'No es una constante.']],regla:'Descompón y luego integra cada fracción como logaritmo.',pista:'A/(x+a) + B/(x+b).',comprobar:()=>cerca(simpson(x=>1/((x+a)*(x+b)),0,T),v)})},
      logistica:(n,r)=>{const T=r.entero(1,4),v=Math.log((T+1)/1)-Math.log((T+2)/2);return prob({enunciado:`Un modelo de crecimiento usa ∫₀^${T} dx/((x + 1)(x + 2)). ¿Cuánto vale? (4 decimales)`,v,dec:4,
        pasos:[paso('Descompón',`1/(x+1) − 1/(x+2)`,'A = 1, B = −1.'),final('Integra',`ln((x+1)/(x+2)) de 0 a ${T} = ${marca(fmt(v,4))}`,'Resultado.')],
        errores:[[Math.log(T+1),'Falta el término de x + 2.'],[-v,'Revisa el orden de los límites.']],regla:'Integra cada fracción por separado.',pista:'1/(x+1) − 1/(x+2).',comprobar:()=>cerca(simpson(x=>1/((x+1)*(x+2)),0,T),v)})}}},
  'ci/sustitucion-trig':{tarjetas:T(['√(a² − x²)','Sustituye x = a sen θ.'],['√(a² + x²)','Sustituye x = a tan θ.'],['√(x² − a²)','Sustituye x = a sec θ.']),
    aplicaciones:{
      cuarto:(n,r)=>{const R=r.entero(1,10),v=Math.PI*R*R/4;return prob({enunciado:`Una pieza tiene forma de cuarto de círculo de radio ${R} cm: su área es ∫₀^${R} √(${R*R} − x²) dx. Calcúlala con x = ${R} sen θ. (2 decimales)`,v,dec:2,unidad:'cm²',
        pasos:[paso('Sustitución',`x = ${R}sen θ, dx = ${R}cos θ dθ; θ de 0 a π/2`,'√(a² − x²) = a cos θ.'),final('Integra',`${R*R}∫cos²θ dθ = ${R*R}·π/4 = ${marca(fmt(v))}`,'cm².')],
        errores:[[Math.PI*R*R,'Ese es el círculo completo.'],[R*R,'Falta el factor π/4.']],regla:'√(a² − x²): x = a sen θ.',pista:'∫₀^{π/2} cos²θ dθ = π/4.',comprobar:()=>cerca(simpson(x=>Math.sqrt(Math.max(0,R*R-x*x)),0,R,20000),v,1e-3)})},
      arco:(n,r)=>{const a=r.entero(1,5),v=Math.asinh(1);return prob({enunciado:`Un cable cumple ∫₀^${a} dx/√(x² + ${a*a}). Usa x = ${a} tan θ. (4 decimales)`,v,dec:4,
        pasos:[paso('Sustitución',`x = ${a}tan θ, √(x² + ${a*a}) = ${a}sec θ`,'dx = '+a+'sec²θ dθ.'),final('∫sec θ dθ',`ln|sec θ + tan θ| de 0 a π/4 = ln(1 + √2) = ${marca(fmt(v,4))}`,'Resultado.')],
        errores:[[Math.PI/4,'Ese es el límite en θ, no la integral.'],[1,'∫sec θ no es tan θ.']],regla:'√(x² + a²): x = a tan θ.',pista:'∫sec θ = ln|sec θ + tan θ|.',comprobar:()=>cerca(simpson(x=>1/Math.sqrt(x*x+a*a),0,a),v)})}}},
  'ci/impropias':{tarjetas:T(['Integral impropia','Límite de integrales: ∫ₐ^∞ f = lím_{t→∞} ∫ₐᵗ f.'],['Converge si…','el límite existe y es finito.'],['∫₁^∞ 1/xᵖ dx','Converge si p > 1 (vale 1/(p − 1)).']),
    aplicaciones:{
      prob:(n,r)=>{const l=r.elegir([0.5,1,2]),a=r.entero(1,4),v=Math.exp(-l*a);return prob({enunciado:`El tiempo de vida de un foco (en años) tiene densidad ${l}e^{−${l}t}. ¿Qué probabilidad hay de que dure más de ${a} años? (∫_${a}^∞) (4 decimales)`,v,dec:4,
        pasos:[paso('Antiderivada',`∫${l}e^{−${l}t} dt = −e^{−${l}t}`,'Exponencial.'),final('Límite',`0 − (−e^{−${l*a}}) = ${marca(fmt(v,4))}`,'Converge.')],
        errores:[[1-v,'Esa es la probabilidad de durar MENOS.'],[l*Math.exp(-l*a),'Esa es la densidad, no el área.']],regla:'P(T > a) = ∫_a^∞ f(t) dt.',pista:'e^{−λt} → 0 cuando t → ∞.',comprobar:()=>cerca(simpson(t=>l*Math.exp(-l*t),a,a+60,40000),v,1e-4)})},
      escape:(n,r)=>{const k=r.entero(2,9)*10,R=r.entero(1,5),v=k/R;return prob({enunciado:`La energía para alejar una nave al infinito es ∫_${R}^∞ ${k}/x² dx (unidades arbitrarias). ¿Cuánto vale?`,v,dec:2,
        pasos:[paso('Antiderivada',`∫${k}/x² dx = −${k}/x`,'Potencia.'),final('Límite',`0 − (−${k}/${R}) = ${marca(fmt(v))}`,'Converge (p = 2 > 1).')],
        errores:[[k,'Falta dividir entre el límite inferior.'],[Infinity,'Converge porque p = 2 > 1.']],regla:'∫_a^∞ 1/x² dx = 1/a.',pista:'−k/x evaluado.',comprobar:()=>cerca(k/R,v)})}}},
  'ci/area':{tarjetas:T(['Área entre f y g en [a, b]','∫ₐᵇ (arriba − abajo) dx.'],['Si la curva cruza el eje x…','separa la integral donde cambia de signo.'],['Para encontrar a y b…','iguala las dos curvas (puntos de intersección).'])},
  'ci/volumenes':{tarjetas:T(['Método de discos (eje x)','V = π∫ₐᵇ [f(x)]² dx.'],['Método de arandelas','V = π∫ₐᵇ (R² − r²) dx.'],['¿Por qué π r²?','Cada rebanada es un disco de área π·radio².'])}
};
